window.GRAMMAR=[{"title":"不仅……而且/还/也……","formula":"不仅 + A，而且/还/也 + B","meaning":"Không những A mà còn B – quan hệ tăng tiến, B có mức độ cao hơn hoặc bổ sung cho A.","usage":"Dùng nhiều trong văn viết và nói trang trọng. Nếu hai vế cùng chủ ngữ, 不仅 đứng sau chủ ngữ; nếu khác chủ ngữ, 不仅 đứng trước chủ ngữ vế 1.","position":"Cùng chủ ngữ: 主语 + 不仅 + 谓语1，而且 + 谓语2. Khác chủ ngữ: 不仅 + 主语1……，而且 + 主语2……","examples":[["这家公司不仅产品质量好，而且售后服务也很周到。","Công ty này không những chất lượng sản phẩm tốt mà dịch vụ hậu mãi cũng rất chu đáo.","zhè jiā gōng sī bù jǐn chǎn pǐn zhì liàng hǎo, ér qiě shòu hòu fú wù yě hěn zhōu dào."],["不仅学生喜欢这位老师，家长也对他评价很高。","Không chỉ học sinh thích thầy giáo này, phụ huynh cũng đánh giá thầy rất cao.","bù jǐn xué shēng xǐ huān zhè wèi lǎo shī, jiā zhǎng yě duì tā píng jià hěn gāo."],["环境污染不仅影响健康，还会造成巨大的经济损失。","Ô nhiễm môi trường không chỉ ảnh hưởng sức khỏe mà còn gây tổn thất kinh tế to lớn.","huán jìng wū rǎn bù jǐn yǐng xiǎng jiàn kāng, hái huì zào chéng jù dà de jīng jì sǔn shī."]],"compare":"不但……而且 nghĩa tương tự nhưng khẩu ngữ hơn; 不仅仅 nhấn mạnh hơn (không chỉ đơn thuần); 不光 dùng trong khẩu ngữ.","errors":"Đặt sai vị trí 不仅 khi hai vế khác chủ ngữ (✗ 学生不仅喜欢他，家长也…… khi muốn nhấn chủ ngữ); dịch máy móc 'mà còn' thành 但是 (✗ 不仅……但是……).","ex":[{"q":"他___会说汉语，而且还会说日语。","o":["不仅","虽然","即使","既然"],"a":0,"e":"不仅……而且 biểu thị tăng tiến."},{"q":"这本书不仅内容丰富，___语言生动。","o":["但是","而且","所以","否则"],"a":1,"e":"Vế sau của 不仅 dùng 而且/还/也."},{"q":"___他同意，连他父母也支持这个决定。","o":["不仅","不仅是","只要","无论"],"a":0,"e":"Khác chủ ngữ: 不仅 đặt trước chủ ngữ vế 1 (连……也 ở vế 2)."},{"q":"这项技术不仅能节约能源，___能减少污染。","o":["却","还","才","就"],"a":1,"e":"不仅……还…… cùng chủ ngữ."},{"q":"Câu nào đúng?","o":["他不仅聪明，但是很努力。","他不仅聪明，而且很努力。","他不仅聪明，所以很努力。","他不仅聪明，就很努力。"],"a":1,"e":"Không ghép 不仅 với 但是/所以."}],"id":1},{"title":"即使……也……","formula":"即使 + giả thiết，也 + kết quả không đổi","meaning":"Cho dù / ngay cả khi A (giả thiết, thường là điều bất lợi) thì kết quả B vẫn không thay đổi.","usage":"Vế 1 thường là điều chưa xảy ra hoặc giả định cực đoan. Vế 2 bắt buộc có 也 (hoặc 还). Văn nói có thể dùng 就算/哪怕.","position":"即使 đứng đầu câu hoặc sau chủ ngữ vế 1; 也 đứng sau chủ ngữ vế 2, trước động từ.","examples":[["即使明天下大雨，比赛也会按时举行。","Cho dù ngày mai mưa to, trận đấu vẫn diễn ra đúng giờ.","jí shǐ míng tiān xià dà yǔ, bǐ sài yě huì àn shí jǔ xíng."],["即使工作再忙，他也坚持每天锻炼身体。","Dù công việc bận đến đâu, anh ấy vẫn kiên trì tập thể dục mỗi ngày.","jí shǐ gōng zuò zài máng, tā yě jiān chí měi tiān duàn liàn shēn tǐ."],["这个问题即使是专家也很难回答。","Vấn đề này ngay cả chuyên gia cũng khó trả lời.","zhè ge wèn tí jí shǐ shì zhuān jiā yě hěn nán huí dá."]],"compare":"尽管……也/但是 nói về sự thật đã xảy ra; 即使 nói về giả thiết. 就算 khẩu ngữ hơn 即使; 哪怕 nhấn mạnh tình huống cực đoan.","errors":"Quên 也 ở vế sau (✗ 即使下雨，比赛会举行); dùng 即使 cho sự thật đã xảy ra (nên dùng 尽管/虽然).","ex":[{"q":"___失败了，我们___要从中吸取经验。","o":["即使/也","既然/就","因为/所以","只要/就"],"a":0,"e":"Giả thiết thất bại, kết quả vẫn không đổi."},{"q":"即使你不说，我___知道是怎么回事。","o":["才","也","却","就是"],"a":1,"e":"即使……也……"},{"q":"___价格再高，他也一定要买这台电脑。","o":["既然","即使","因为","只有"],"a":1,"e":"Giả thiết cực đoan: 再高."},{"q":"Câu nào đúng?","o":["即使天气不好，我们会去。","即使天气不好，我们也会去。","即使天气不好，所以我们去。","即使天气不好，我们就去。"],"a":1,"e":"Vế sau phải có 也."},{"q":"昨天下雨了，___我们还是去爬山了。（sự thật đã xảy ra）","o":["即使","尽管","只要","一旦"],"a":1,"e":"Sự thật đã xảy ra dùng 尽管……还是, không dùng 即使."}],"id":2},{"title":"既然……就……","formula":"既然 + sự thật đã biết，就/也/还 + kết luận","meaning":"Đã ... thì ... – dựa vào một sự thật đã xác định để đưa ra kết luận, lời khuyên hay quyết định.","usage":"Vế 1 là sự thật đã xảy ra hoặc hai bên đều biết; vế 2 thường là đề nghị, suy luận, câu hỏi tu từ.","position":"既然 đặt đầu câu hoặc sau chủ ngữ; 就 đứng sau chủ ngữ vế 2.","examples":[["既然你已经决定了，我就不再劝你了。","Đã quyết định rồi thì tôi không khuyên nữa.","jì rán nǐ yǐ jīng jué dìng le, wǒ jiù bù zài quàn nǐ le."],["既然大家都同意，那就按这个方案执行吧。","Mọi người đều đồng ý rồi thì cứ thực hiện theo phương án này.","jì rán dà jiā dōu tóng yì, nà jiù àn zhè ge fāng àn zhí xíng ba."],["既然身体不舒服，何必还要去上班呢？","Đã không khỏe thì cần gì phải đi làm?","jì rán shēn tǐ bù shū fú, hé bì hái yào qù shàng bān ne?"]],"compare":"因为……所以 chỉ nêu nguyên nhân – kết quả khách quan; 既然 nhấn mạnh suy luận chủ quan dựa trên sự thật. 既然 không dùng cho giả thiết (giả thiết dùng 如果).","errors":"Dùng 既然……所以 (✗); dùng 既然 cho điều chưa xảy ra (✗ 既然明天下雨 → 如果明天下雨).","ex":[{"q":"___你这么喜欢，___买下来吧。","o":["既然/就","即使/也","虽然/但是","只有/才"],"a":0,"e":"Dựa vào sự thật để đưa ra đề nghị."},{"q":"既然问题已经出现了，我们___要想办法解决。","o":["才","就","却","还是"],"a":1,"e":"既然……就……"},{"q":"___明天下雨，比赛就推迟。（giả thiết）","o":["既然","如果","尽管","即使"],"a":1,"e":"Giả thiết dùng 如果."},{"q":"既然他不愿意来，___别勉强他了。","o":["所以","那就","但是","而且"],"a":1,"e":"那就 thường dùng sau 既然."},{"q":"Câu nào đúng?","o":["既然你来了，所以坐一会儿吧。","既然你来了，就坐一会儿吧。","既然你来了，也是坐一会儿吧。","既然你来了，才坐一会儿吧。"],"a":1,"e":"Không dùng 所以 với 既然."}],"id":3},{"title":"无论/不管……都/也……","formula":"无论/不管 + từ nghi vấn / A还是B / 多么…… ，都/也 + kết quả","meaning":"Bất kể / dù ... thế nào thì kết quả vẫn như vậy (điều kiện không loại trừ).","usage":"Vế 1 bắt buộc có từ nghi vấn (什么、谁、怎么、多么), cấu trúc lựa chọn (A还是B) hoặc chính phản (去不去). 无论 trang trọng hơn 不管.","position":"无论/不管 đầu câu; 都/也 đứng trước động từ vế 2.","examples":[["无论遇到什么困难，我们都不能放弃。","Dù gặp khó khăn gì, chúng ta cũng không được bỏ cuộc.","wú lùn yù dào shén me kùn nán, wǒ men dōu bù néng fàng qì."],["不管你同意不同意，这件事都得这么办。","Dù bạn đồng ý hay không, việc này vẫn phải làm như vậy.","bù guǎn nǐ tóng yì bù tóng yì, zhè jiàn shì dōu dé zhè me bàn."],["无论是城市还是农村，环境保护都非常重要。","Dù là thành thị hay nông thôn, bảo vệ môi trường đều rất quan trọng.","wú lùn shì chéng shì hái shì nóng cūn, huán jìng bǎo hù dōu fēi cháng zhòng yào."]],"compare":"即使 nói về một giả thiết cụ thể; 无论 bao quát mọi khả năng. 不管 còn có nghĩa 'không quan tâm' (我不管).","errors":"Thiếu từ nghi vấn ở vế 1 (✗ 无论天气很冷，他都去 → 无论天气多冷); dùng 或者 thay vì 还是 (✗ 无论你或者他).","ex":[{"q":"无论天气___冷，他都坚持跑步。","o":["很","多么","非常","太"],"a":1,"e":"无论 phải đi với từ nghi vấn/多么."},{"q":"不管是大人___小孩，都喜欢这部动画片。","o":["或者","还是","和","而且"],"a":1,"e":"无论/不管 A 还是 B."},{"q":"无论做什么工作，___要认真负责。","o":["才","都","就","却"],"a":1,"e":"无论……都……"},{"q":"___你去不去，我都要去。","o":["即使","不管","既然","只有"],"a":1,"e":"Cấu trúc chính phản 去不去 dùng 不管/无论."},{"q":"Câu nào đúng?","o":["无论条件很差，他都不抱怨。","无论条件多差，他都不抱怨。","无论条件差，他也抱怨。","无论条件多差，他就不抱怨。"],"a":1,"e":"Cần 多 + tính từ; vế sau dùng 都."}],"id":4},{"title":"只要……就…… / 只有……才……","formula":"只要 A，就 B（điều kiện đủ） · 只有 A，才 B（điều kiện cần duy nhất）","meaning":"只要: chỉ cần A là có B (điều kiện đủ, dễ đạt). 只有: chỉ có A mới có B (điều kiện bắt buộc, thiếu A thì không được).","usage":"只要 đi với 就; 只有 đi với 才. Không đảo cặp.","position":"Đầu câu hoặc sau chủ ngữ vế 1; 就/才 trước động từ vế 2.","examples":[["只要你认真复习，就一定能通过考试。","Chỉ cần bạn ôn tập nghiêm túc thì nhất định sẽ thi đỗ.","zhǐ yào nǐ rèn zhēn fù xí, jiù yí dìng néng tōng guò kǎo shì."],["只有坚持练习，才能真正提高口语水平。","Chỉ có kiên trì luyện tập mới thật sự nâng cao được khẩu ngữ.","zhǐ yǒu jiān chí liàn xí, cái néng zhēn zhèng tí gāo kǒu yǔ shuǐ píng."],["只要有网络，在哪儿都可以办公。","Chỉ cần có mạng, ở đâu cũng có thể làm việc.","zhǐ yào yǒu wǎng luò, zài nǎ ér dōu kě yǐ bàn gōng."]],"compare":"除非……才/否则: trừ phi... mới...; 一旦……就: một khi (nhấn sự kiện bất ngờ). 只要 nhấn 'dễ', 只有 nhấn 'duy nhất'.","errors":"Ghép sai 只要……才 hoặc 只有……就 (✗); nhầm vị trí 才 sau động từ.","ex":[{"q":"只要你说实话，我___原谅你。","o":["才","就","都","却"],"a":1,"e":"只要……就……"},{"q":"只有通过面试，___能被录用。","o":["就","才","也","都"],"a":1,"e":"只有……才……"},{"q":"___多读多写，___能写出好文章。","o":["只要/才","只有/才","只有/就","即使/也"],"a":1,"e":"Điều kiện bắt buộc: 只有……才."},{"q":"___有时间，我就去看你。","o":["只有","只要","无论","尽管"],"a":1,"e":"Điều kiện đủ dễ đạt."},{"q":"Câu nào đúng?","o":["只要努力，才会成功。","只有努力，才会成功。","只有努力，就会成功。","只有努力，都会成功。"],"a":1,"e":"只有 đi với 才."}],"id":5},{"title":"宁可……也不……","formula":"宁可 + A（chấp nhận điều thiệt），也不 + B（kiên quyết không làm）","meaning":"Thà A còn hơn B – sau khi so sánh, chọn A dù A có thiệt thòi, kiên quyết không chọn B.","usage":"Vế 1 là lựa chọn bất lợi mà người nói chấp nhận; vế 2 thường dùng 也不/也要. Biến thể: 宁可 A，也要 B (thà A cũng phải B).","position":"宁可 sau chủ ngữ, trước động từ vế 1.","examples":[["我宁可多花点儿钱，也不买质量差的东西。","Tôi thà tốn thêm tiền còn hơn mua đồ kém chất lượng.","wǒ nìng kě duō huā diǎn ér qián, yě bù mǎi zhì liàng chà de dōng xī."],["他宁可自己吃亏，也不愿意让朋友为难。","Anh ấy thà mình chịu thiệt còn hơn làm bạn khó xử.","tā nìng kě zì jǐ chī kuī, yě bù yuàn yì ràng péng yǒu wéi nán."],["我们宁可慢一点，也要保证安全。","Chúng tôi thà chậm một chút cũng phải đảm bảo an toàn.","wǒ men nìng kě màn yì diǎn, yě yào bǎo zhèng ān quán."]],"compare":"与其 A 不如 B: chọn B (vế sau); 宁可 A 也不 B: chọn A (vế trước). Đây là điểm dễ nhầm nhất.","errors":"Hiểu ngược lựa chọn: với 宁可, điều được chọn ở vế trước; dùng 宁可……但是 (✗).","ex":[{"q":"我宁可走路回家，___坐他的车。","o":["也不","而且","就","但是"],"a":0,"e":"宁可……也不……"},{"q":"他___饿着肚子，也不吃别人的东西。","o":["与其","宁可","不如","即使"],"a":1,"e":"Chấp nhận thiệt (đói), kiên quyết không làm."},{"q":"'我宁可加班，也不把工作拖到明天。' Người nói chọn gì?","o":["Để việc sang mai","Làm thêm giờ","Không làm gì","Nhờ người khác"],"a":1,"e":"Với 宁可, lựa chọn ở vế trước."},{"q":"我们宁可少赚一点儿，___要保证产品质量。","o":["也","才","就","还是"],"a":0,"e":"宁可……也要……"},{"q":"Câu nào đúng?","o":["我宁可站着，不如坐着。","我宁可站着，也不坐那把脏椅子。","我宁可站着，所以不坐。","我宁可站着，就不坐。"],"a":1,"e":"宁可……也不……"}],"id":6},{"title":"与其……不如……","formula":"与其 + A（không chọn），不如 + B（chọn）","meaning":"Thay vì A chi bằng B – so sánh hai cách làm, người nói chọn B.","usage":"Dùng để đưa ra lời khuyên hay lựa chọn hợp lý hơn. 不如 có thể thay bằng 还不如/倒不如 để nhấn mạnh.","position":"与其 đầu vế 1 (sau chủ ngữ nếu có); 不如 đầu vế 2.","examples":[["与其在家里发愁，不如出去找找解决的办法。","Thay vì ở nhà lo lắng, chi bằng ra ngoài tìm cách giải quyết.","yǔ qí zài jiā lǐ fā chóu, bù rú chū qù zhǎo zhǎo jiě jué de bàn fǎ."],["与其临时抱佛脚，倒不如平时多下功夫。","Thay vì nước đến chân mới nhảy, chi bằng ngày thường chăm chỉ hơn.","yǔ qí lín shí bào fó jiǎo, dào bù rú píng shí duō xià gōng fū."],["与其花钱买新的，不如把旧的修一修。","Thay vì tiêu tiền mua cái mới, chi bằng sửa lại cái cũ.","yǔ qí huā qián mǎi xīn de, bù rú bǎ jiù de xiū yī xiū."]],"compare":"Ngược với 宁可: 与其 A 不如 B chọn B; 宁可 A 也不 B chọn A.","errors":"Dùng 与其……还是…… (✗); nhầm bên được chọn.","ex":[{"q":"与其坐着等，___主动去问问。","o":["不如","宁可","而且","即使"],"a":0,"e":"与其……不如……"},{"q":"___花时间抱怨，不如想办法改变。","o":["宁可","与其","只要","尽管"],"a":1,"e":"与其 A 不如 B."},{"q":"'与其坐出租车，不如坐地铁。' Người nói khuyên gì?","o":["Đi taxi","Đi tàu điện ngầm","Đi bộ","Không đi"],"a":1,"e":"Chọn vế sau 不如."},{"q":"与其让他一个人去，还___我陪他一起去。","o":["不如","宁可","就是","而且"],"a":0,"e":"还不如 nhấn mạnh."},{"q":"Câu nào đúng?","o":["与其看电视，还是看书。","与其看电视，不如看书。","与其看电视，也不看书。","与其看电视，就看书。"],"a":1,"e":"与其 đi với 不如."}],"id":7},{"title":"尽管……但是/却/还是……","formula":"尽管 + sự thật，但是/可是/却/还是 + kết quả trái ngược","meaning":"Mặc dù A (sự thật) nhưng vẫn B – quan hệ nhượng bộ, giống 虽然 nhưng trang trọng hơn.","usage":"Vế 1 là sự thật đã có. 尽管 còn là phó từ nghĩa 'cứ việc' (有问题尽管问).","position":"尽管 đầu câu hoặc sau chủ ngữ; 却 đứng sau chủ ngữ vế 2, 但是 đứng trước chủ ngữ.","examples":[["尽管困难很多，但是我们还是按时完成了任务。","Mặc dù khó khăn nhiều, nhưng chúng tôi vẫn hoàn thành nhiệm vụ đúng hạn.","jǐn guǎn kùn nán hěn duō, dàn shì wǒ men hái shì àn shí wán chéng le rèn wù."],["他尽管年纪大了，却仍然坚持学习外语。","Ông ấy tuy đã lớn tuổi nhưng vẫn kiên trì học ngoại ngữ.","tā jǐn guǎn nián jì dà le, què réng rán jiān chí xué xí wài yǔ."],["你有什么问题尽管问，别客气。","Có câu hỏi gì cứ hỏi, đừng ngại.","nǐ yǒu shén me wèn tí jǐn guǎn wèn, bié kè qì."]],"compare":"即使 = giả thiết; 尽管 = sự thật. 虽然 khẩu ngữ hơn. 却 là phó từ, phải đặt sau chủ ngữ (✗ 却他).","errors":"Đặt 却 trước chủ ngữ (✗ 尽管很累，却他还在工作); dùng 尽管 cho giả thiết.","ex":[{"q":"尽管他很努力，___成绩一直不理想。","o":["所以","但是","而且","就"],"a":1,"e":"尽管……但是……"},{"q":"尽管天气很冷，他___只穿了一件衬衫。","o":["却","才","都","也就"],"a":0,"e":"却 đặt sau chủ ngữ."},{"q":"有什么需要，你___告诉我。","o":["尽管","即使","既然","只要"],"a":0,"e":"尽管 = cứ việc."},{"q":"___外面下着大雨，球迷们还是准时来到了体育场。","o":["即使","尽管","只要","无论"],"a":1,"e":"Sự thật đang xảy ra: 尽管."},{"q":"Câu nào đúng?","o":["尽管他很忙，却他每天都运动。","尽管他很忙，他却每天都运动。","尽管他很忙，所以每天都运动。","尽管他很忙，他就每天都运动。"],"a":1,"e":"却 đứng sau chủ ngữ."}],"id":8},{"title":"以便 / 以免","formula":"A，以便 + B（mục đích mong muốn）· A，以免 + C（tránh điều không mong muốn）","meaning":"以便: để tiện cho, nhằm (đạt được B). 以免: để tránh, kẻo (C xảy ra).","usage":"Dùng ở đầu vế 2, văn viết. 以免 ≈ 免得 (khẩu ngữ hơn) ≈ 省得.","position":"Đứng đầu vế sau, vế sau thường lược chủ ngữ.","examples":[["请留下您的电话号码，以便我们及时与您联系。","Xin để lại số điện thoại để chúng tôi kịp thời liên lạc với ngài.","qǐng liú xià nín de diàn huà hào mǎ, yǐ biàn wǒ men jí shí yǔ nín lián xì."],["出门前要检查好门窗，以免发生意外。","Trước khi ra ngoài phải kiểm tra cửa để tránh xảy ra sự cố.","chū mén qián yào jiǎn chá hǎo mén chuāng, yǐ miǎn fā shēng yì wài."],["大家提前做好准备，以便会议顺利进行。","Mọi người chuẩn bị trước để cuộc họp diễn ra suôn sẻ.","dà jiā tí qián zuò hǎo zhǔn bèi, yǐ biàn huì yì shùn lì jìn xíng."]],"compare":"为了 đặt ở vế đầu; 以便/以免 đặt ở vế sau. 以免 theo sau là điều xấu.","errors":"Dùng 以便 trước điều xấu hoặc 以免 trước điều tốt; đặt 以便 ở vế đầu như 为了.","ex":[{"q":"请把重要文件备份一下，___丢失。","o":["以便","以免","因此","从而"],"a":1,"e":"Tránh điều xấu (mất)."},{"q":"我们应该提前订票，___选到好座位。","o":["以免","以便","免得","否则"],"a":1,"e":"Đạt mục đích tốt."},{"q":"开车时不要看手机，___出事故。","o":["以便","以免","因而","进而"],"a":1,"e":"Tránh tai nạn."},{"q":"他把会议时间记在本子上，___忘了。","o":["免得","以便","以致","从而"],"a":0,"e":"免得 ≈ 以免."},{"q":"Câu nào đúng?","o":["以便方便顾客，商店延长了营业时间。","商店延长了营业时间，以便方便顾客。","商店延长了营业时间，以免方便顾客。","以免顾客方便，商店延长了时间。"],"a":1,"e":"以便 đặt ở vế sau."}],"id":9},{"title":"一旦……就……","formula":"一旦 + A（tình huống có thể xảy ra），就 + B","meaning":"Một khi A xảy ra thì B – nhấn mạnh A là bước ngoặt, thường dẫn đến hậu quả (tốt hoặc xấu).","usage":"Dùng cho cả tương lai (giả thiết) và quá khứ (đã từng xảy ra). Văn viết.","position":"一旦 đứng sau chủ ngữ hoặc đầu câu; 就 trước động từ vế 2.","examples":[["一旦养成了坏习惯，就很难改掉。","Một khi đã hình thành thói quen xấu thì rất khó bỏ.","yí dàn yǎng chéng le huài xí guàn, jiù hěn nán gǎi diào."],["这种病一旦发现得晚，治疗就会很困难。","Bệnh này một khi phát hiện muộn thì điều trị sẽ rất khó.","zhè zhǒng bìng yí dàn fā xiàn dé wǎn, zhì liáo jiù huì hěn kùn nán."],["机会一旦错过，就不会再来。","Cơ hội một khi đã bỏ lỡ thì sẽ không quay lại.","jī huì yí dàn cuò guò, jiù bú huì zài lái."]],"compare":"只要……就 nhấn điều kiện đủ; 一旦 nhấn thời điểm 'một khi xảy ra'. 如果 trung tính hơn.","errors":"Dùng 一旦 cho việc thường xuyên, lặp lại (✗ 我一旦有空就去游泳 – nên dùng 一……就/只要).","ex":[{"q":"信任___失去，就很难再找回来。","o":["一旦","即使","既然","尽管"],"a":0,"e":"一旦……就……"},{"q":"一旦发生火灾，___要立刻拨打119。","o":["才","就","也","却"],"a":1,"e":"一旦……就……"},{"q":"这个秘密___被公开，后果不堪设想。","o":["只有","一旦","与其","宁可"],"a":1,"e":"Một khi bị công khai."},{"q":"Câu nào tự nhiên nhất?","o":["我一旦起床就刷牙。","一旦出现问题，就马上通知我。","一旦你是学生，就学习。","一旦天气好，也去公园。"],"a":1,"e":"一旦 dùng cho tình huống đặc biệt, bước ngoặt."},{"q":"公司一旦破产，员工们___会失业。","o":["就","才","都是","却"],"a":0,"e":"一旦……就……"}],"id":10},{"title":"何况 / 况且","formula":"A 都/尚且……，何况 B 呢？· 况且 + lý do bổ sung","meaning":"何况: huống hồ, huống chi (A còn vậy, B càng phải vậy) – thường ở câu hỏi tu từ. 况且: hơn nữa, vả lại (bổ sung lý do).","usage":"何况 thường đi với 连……都/尚且 ở vế trước. 况且 dùng khi liệt kê thêm lý do, có thể đi với 又/也/还.","position":"Đầu vế sau.","examples":[["这道题连老师都不会做，何况我们呢？","Câu này đến thầy còn không làm được, huống hồ chúng tôi?","zhè dào tí lián lǎo shī dōu bú huì zuò, hé kuàng wǒ men ne?"],["这家餐厅太远了，况且价格也不便宜，我们换一家吧。","Nhà hàng này xa quá, vả lại giá cũng không rẻ, ta đổi chỗ khác đi.","zhè jiā cān tīng tài yuǎn le, kuàng qiě jià gé yě bù biàn yí, wǒ men huàn yī jiā ba."],["大人都受不了这么热的天气，更何况孩子呢。","Người lớn còn không chịu nổi trời nóng thế này, huống chi trẻ con.","dà rén dōu shòu bù liǎo zhè me rè de tiān qì, gèng hé kuàng hái zi ne."]],"compare":"何况 = so sánh mức độ (A đã thế thì B càng); 况且 = thêm lý do cùng chiều; 而且 trung tính.","errors":"Dùng 况且 ở câu so sánh mức độ (✗ 连专家都不懂，况且我呢); quên 呢 cuối câu với 何况.","ex":[{"q":"这么重的箱子连小王都搬不动，___是我呢？","o":["况且","何况","而且","并且"],"a":1,"e":"So sánh mức độ, câu hỏi tu từ."},{"q":"时间来不及了，___外面还下着雨，我们别去了。","o":["何况","况且","尚且","以免"],"a":1,"e":"Bổ sung lý do."},{"q":"___都看不懂，何况外国人呢？","o":["中国人尚且","中国人况且","中国人而且","中国人也就"],"a":0,"e":"尚且……何况……"},{"q":"这件衣服太贵了，况且颜色我___不喜欢。","o":["也","才","却是","就"],"a":0,"e":"况且……也……"},{"q":"Câu nào đúng?","o":["他连饭都吃不起，何况买车呢？","他连饭都吃不起，况且买车呢？","他连饭都吃不起，而且买车呢？","他连饭都吃不起，所以买车呢？"],"a":0,"e":"何况 + câu hỏi tu từ."}],"id":11},{"title":"难怪 / 怪不得","formula":"难怪/怪不得 + kết quả，原来 + nguyên nhân","meaning":"Thảo nào, hèn gì – sau khi biết nguyên nhân, người nói hiểu ra một hiện tượng trước đó thấy lạ.","usage":"Thường đi với 原来 (hóa ra) để nói nguyên nhân. 难怪 còn là động từ 'không trách được' (这也难怪他).","position":"Đứng đầu câu hoặc trước chủ ngữ của vế nêu hiện tượng.","examples":[["原来他在中国住了十年，难怪汉语说得这么好。","Hóa ra anh ấy sống ở Trung Quốc mười năm, thảo nào nói tiếng Trung giỏi vậy.","yuán lái tā zài zhōng guó zhù le shí nián, nán guài hàn yǔ shuō dé zhè me hǎo."],["怪不得今天路上车这么少，原来是放假了。","Hèn gì hôm nay đường vắng xe, hóa ra là ngày nghỉ.","guài bù dé jīn tiān lù shàng chē zhè me shǎo, yuán lái shì fàng jià le."],["他第一次做这种工作，出点儿错也难怪。","Lần đầu anh ấy làm việc này, có sai sót chút cũng không trách được.","tā dì yī cì zuò zhè zhǒng gōng zuò, chū diǎn ér cuò yě nán guài."]],"compare":"难怪 = 怪不得 khi là phó từ; 怪不得 khẩu ngữ hơn. 原来 nêu nguyên nhân mới phát hiện.","errors":"Đặt nguyên nhân sau 难怪 (✗ 难怪他在中国住过 – 难怪 phải đi với hiện tượng).","ex":[{"q":"她天天练习，___进步这么快。","o":["难怪","何况","况且","即使"],"a":0,"e":"Hiểu ra nguyên nhân."},{"q":"怪不得他没来，___他生病了。","o":["原来","本来","从来","后来"],"a":0,"e":"原来 nêu nguyên nhân vừa biết."},{"q":"___房间这么冷，原来窗户没关。","o":["既然","怪不得","只要","与其"],"a":1,"e":"Thảo nào."},{"q":"'难怪' gần nghĩa nhất với:","o":["怪不得","不至于","不得不","免得"],"a":0,"e":"难怪 = 怪不得."},{"q":"Câu nào đúng?","o":["难怪他每天跑步，原来身体这么好。","原来他每天跑步，难怪身体这么好。","难怪他身体好，所以每天跑步。","原来身体好，难怪他每天跑步。"],"a":1,"e":"难怪 + hiện tượng, 原来 + nguyên nhân."}],"id":12},{"title":"不至于","formula":"（还）不至于 + mức độ quá đáng / 至于……吗？","meaning":"Không đến nỗi, chưa đến mức – phủ định khả năng xảy ra một tình huống quá mức.","usage":"Thường đi với 还、也、总. Dạng hỏi tu từ 至于……吗？= có cần phải đến mức đó không?","position":"Trước động từ / cụm động từ, sau chủ ngữ.","examples":[["这次考试虽然难，但他准备得很充分，不至于不及格。","Kỳ thi này tuy khó, nhưng cậu ấy chuẩn bị kỹ, không đến nỗi trượt.","zhè cì kǎo shì suī rán nán, dàn tā zhǔn bèi dé hěn chōng fèn, bù zhì yú bù jí gé."],["一点儿小事，至于发这么大的火吗？","Chuyện nhỏ thế, có cần nổi giận to vậy không?","yì diǎn ér xiǎo shì, zhì yú fā zhè me dà de huǒ ma?"],["只要按时吃药，病情还不至于恶化。","Chỉ cần uống thuốc đúng giờ, bệnh chưa đến mức trở nặng.","zhǐ yào àn shí chī yào, bìng qíng hái bù zhì yú è huà."]],"compare":"不至于 (không đến nỗi) khác 至于 (giới từ: còn về, xem bài 15). 以至于: đến nỗi (kết quả).","errors":"Dùng 不至于 cho tình huống bình thường không quá mức (✗ 他不至于吃饭); nhầm với 至于 'còn về'.","ex":[{"q":"他只是有点儿感冒，___住院吧。","o":["不至于","以至于","至于","甚至于"],"a":0,"e":"Không đến mức."},{"q":"就迟到了五分钟，___这么生气吗？","o":["至于","不至于","以至于","关于"],"a":0,"e":"至于……吗？ hỏi tu từ."},{"q":"我们提前出发，应该___错过飞机。","o":["不至于","以至","至于","终于"],"a":0,"e":"Không đến nỗi."},{"q":"'不至于' nghĩa là:","o":["Không đến nỗi","Còn về","Đến nỗi","Cuối cùng"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["他再笨，也不至于连这个都不会。","他再笨，也至于连这个都不会。","他再笨，不至于以至这个不会。","他不至于很笨吗。"],"a":0,"e":"再……也不至于……"}],"id":13},{"title":"免得 / 省得","formula":"A，免得/省得 + B（điều không mong muốn）","meaning":"Để khỏi, kẻo – làm A để tránh B xảy ra. Khẩu ngữ của 以免.","usage":"Đứng đầu vế sau. 省得 thiên về tránh phiền phức, tốn công.","position":"Đầu vế sau; vế sau có thể có chủ ngữ riêng.","examples":[["你到了给我打个电话，免得我担心。","Bạn đến nơi thì gọi cho tôi, kẻo tôi lo.","nǐ dào le gěi wǒ dǎ gè diàn huà, miǎn de wǒ dān xīn."],["多带件衣服吧，免得着凉。","Mang thêm áo đi, kẻo bị cảm lạnh.","duō dài jiàn yī fú ba, miǎn de zháo liáng."],["我们直接在网上买，省得跑来跑去。","Ta mua trực tiếp trên mạng, đỡ phải chạy đi chạy lại.","wǒ men zhí jiē zài wǎng shàng mǎi, shěng de pǎo lái pǎo qù."]],"compare":"以免: văn viết; 免得/省得: khẩu ngữ. 以便: mục đích tốt.","errors":"Theo sau là điều tốt (✗ 免得成功); dịch 'để' thành 免得 trong mọi trường hợp.","ex":[{"q":"早点儿睡吧，___明天起不来。","o":["免得","以便","从而","因此"],"a":0,"e":"Tránh điều xấu."},{"q":"把地址写下来，___忘了。","o":["省得","以便","以至","进而"],"a":0,"e":"Tránh quên."},{"q":"'免得' gần nghĩa nhất với:","o":["以免","以便","以至","以为"],"a":0,"e":""},{"q":"你还是亲自去一趟吧，___他误会。","o":["以便","免得","何况","况且"],"a":1,"e":"Tránh hiểu lầm."},{"q":"Câu nào đúng?","o":["多练习，免得考试考好。","多练习，免得考试不及格。","免得不及格，多练习就。","多练习，免得以便及格。"],"a":1,"e":"Sau 免得 là điều không mong muốn."}],"id":14},{"title":"至于","formula":"A……，至于 B，……","meaning":"Còn về, còn như – chuyển sang một đề tài liên quan khác.","usage":"Giới từ dẫn ra chủ đề mới ở đầu câu/phân câu. Lưu ý phân biệt với 不至于 (không đến nỗi).","position":"Đầu câu hoặc đầu phân câu sau.","examples":[["这个方案大家先讨论一下，至于具体怎么做，下次开会再决定。","Phương án này mọi người thảo luận trước, còn cụ thể làm thế nào thì lần họp sau quyết định.","zhè ge fāng àn dà jiā xiān tǎo lùn yī xià, zhì yú jù tǐ zěn me zuò, xià cì kāi huì zài jué dìng."],["我只负责翻译，至于内容是否准确，请问作者。","Tôi chỉ phụ trách dịch, còn nội dung có chính xác không thì hỏi tác giả.","wǒ zhǐ fù zé fān yì, zhì yú nèi róng shì fǒu zhǔn què, qǐng wèn zuò zhě."],["他去过很多国家，至于具体去过哪些，我就不清楚了。","Anh ấy đi nhiều nước, còn cụ thể những nước nào thì tôi không rõ.","tā qù guò hěn duō guó jiā, zhì yú jù tǐ qù guò nǎ xiē, wǒ jiù bù qīng chǔ le."]],"compare":"关于: về (giới thiệu phạm vi chung); 至于: chuyển chủ đề sau khi đã nói một điều trước đó.","errors":"Dùng 至于 ở câu đầu tiên khi chưa có chủ đề trước (nên dùng 关于).","ex":[{"q":"我同意去旅游，___去哪儿，你们决定吧。","o":["至于","关于","对于","由于"],"a":0,"e":"Chuyển chủ đề."},{"q":"___这个问题，我们已经讨论过了。（mở đầu, giới thiệu phạm vi）","o":["至于","关于","以至","不至于"],"a":1,"e":"Giới thiệu phạm vi chung: 关于."},{"q":"我只知道他辞职了，___原因，我也不知道。","o":["至于","以至于","不至于","甚至"],"a":0,"e":"Còn về nguyên nhân."},{"q":"'至于' trong câu '至于价格，可以再商量' nghĩa là:","o":["Không đến nỗi","Còn về","Đến mức","Bởi vì"],"a":1,"e":""},{"q":"Câu nào đúng?","o":["衣服我买了，至于鞋子，下次再说。","衣服我买了，以至鞋子，下次再说。","衣服我买了，不至于鞋子下次。","至于衣服我买了，至于。"],"a":0,"e":""}],"id":15},{"title":"便 / 就（书面语）","formula":"主语 + 便 + 动词（= 就）","meaning":"便 là dạng văn viết của 就: thì, liền, ngay – nối hành động tiếp nối hoặc kết quả.","usage":"Hay gặp trong văn bản đọc hiểu HSK 6: 一……便……、只要……便……、稍……便……. Không dùng 便 với nghĩa nhấn mạnh 'chính là' trong khẩu ngữ (这就是 → văn viết 这便是).","position":"Sau chủ ngữ, trước động từ.","examples":[["他一回到家便打开电脑开始工作。","Anh ấy vừa về nhà liền mở máy tính bắt đầu làm việc.","tā yī huí dào jiā biàn dǎ kāi diàn nǎo kāi shǐ gōng zuò."],["只要稍加注意，便能避免这类错误。","Chỉ cần chú ý một chút là có thể tránh lỗi này.","zhǐ yào shāo jiā zhù yì, biàn néng bì miǎn zhè lèi cuò wù."],["这便是我选择这份工作的原因。","Đây chính là lý do tôi chọn công việc này.","zhè biàn shì wǒ xuǎn zé zhè fèn gōng zuò de yuán yīn."]],"compare":"便 = 就 về nghĩa nhưng trang trọng; 就 còn nghĩa 'chỉ' (就他一个人), 便 không có nghĩa này.","errors":"Dùng 便 với nghĩa 'chỉ' (✗ 便他一个人来了); đặt 便 trước chủ ngữ (✗ 便他走了).","ex":[{"q":"他一听到这个消息，___激动得说不出话来。","o":["便","才","却","再"],"a":0,"e":"一……便…… = 一……就……"},{"q":"只要坚持下去，___一定会成功。","o":["便","才","都","却"],"a":0,"e":"只要……便……"},{"q":"'这便是答案' – 便 tương đương:","o":["就","才","也","都"],"a":0,"e":""},{"q":"天刚亮，他们___出发了。","o":["才","便","再","又是"],"a":1,"e":"便 = 就."},{"q":"Câu nào đúng?","o":["便他一个人来了。","他一到车站便上了车。","他便一个人吗？","便是他走了。"],"a":1,"e":"便 đứng sau chủ ngữ."}],"id":16},{"title":"凡是……都……","formula":"凡是 + phạm vi，都 + kết luận","meaning":"Phàm là, hễ là – bao gồm tất cả các đối tượng trong phạm vi, không có ngoại lệ.","usage":"Văn viết, thường dùng trong quy định, thông báo. Vế sau bắt buộc có 都/一律/全.","position":"Đầu câu.","examples":[["凡是参加比赛的选手，都必须提前报名。","Phàm là thí sinh tham gia cuộc thi đều phải đăng ký trước.","fán shì cān jiā bǐ sài de xuǎn shǒu, dōu bì xū tí qián bào míng."],["凡是去过那里的人，都对那儿的风景赞不绝口。","Ai từng đến đó đều không ngớt lời khen phong cảnh nơi ấy.","fán shì qù guò nà lǐ de rén, dōu duì nà ér de fēng jǐng zàn bù jué kǒu."],["凡是不符合规定的申请，一律不予受理。","Mọi đơn không phù hợp quy định đều không được thụ lý.","fán shì bù fú hé guī dìng de shēn qǐng, yī lǜ bù yǔ shòu lǐ."]],"compare":"所有……都: tất cả (trung tính); 凡是 nhấn mạnh 'không có ngoại lệ', trang trọng hơn.","errors":"Đặt 凡是 sau chủ ngữ (✗ 学生凡是); quên 都 ở vế sau.","ex":[{"q":"___有经验的人，___知道这样做很危险。","o":["凡是/都","只要/才","即使/也","既然/就"],"a":0,"e":"凡是……都……"},{"q":"凡是年满十八岁的公民，___有选举权。","o":["才","都","就是","却"],"a":1,"e":"Vế sau cần 都."},{"q":"___迟到的同学，一律不能参加考试。","o":["凡是","即使","尽管","以便"],"a":0,"e":"Phạm vi không ngoại lệ."},{"q":"'凡是' gần nghĩa nhất:","o":["所有的","有的","个别","某些"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["学生凡是都要交作业。","凡是学生都要交作业。","凡是学生要交作业才。","凡是学生，所以交作业。"],"a":1,"e":"凡是 đầu câu."}],"id":17},{"title":"就算……也……","formula":"就算 + giả thiết，也 + kết quả","meaning":"Cho dù, coi như là – giả thiết nhượng bộ, khẩu ngữ của 即使.","usage":"Thường dùng khi nói chuyện, tranh luận. 就算 còn là động từ 'coi như' (这就算是我的心意).","position":"Đầu câu hoặc sau chủ ngữ.","examples":[["就算你说得对，也不应该用这种态度跟别人说话。","Cho dù bạn nói đúng, cũng không nên dùng thái độ đó nói chuyện với người khác.","jiù suàn nǐ shuō dé duì, yě bù yīng gāi yòng zhè zhǒng tài dù gēn bié rén shuō huà."],["就算再难，我也要试一试。","Dù khó hơn nữa, tôi cũng muốn thử.","jiù suàn zài nán, wǒ yě yào shì yī shì."],["这点钱不多，就算是我的一点儿心意吧。","Chút tiền này không nhiều, coi như tấm lòng của tôi.","zhè diǎn qián bù duō, jiù suàn shì wǒ de yì diǎn ér xīn yì ba."]],"compare":"就算 = 即使 = 哪怕 (giả thiết). 就算 khẩu ngữ, 即使 trung tính, 哪怕 nhấn tình huống cực đoan.","errors":"Thiếu 也 ở vế sau; dùng cho sự thật đã xảy ra.","ex":[{"q":"___明天不下雨，我们___不去爬山了。","o":["就算/也","既然/就","只要/就","只有/才"],"a":0,"e":"就算……也……"},{"q":"就算你不告诉我，我___会知道的。","o":["也","才","就是","可是"],"a":0,"e":""},{"q":"'就算' gần nghĩa nhất:","o":["即使","既然","因为","所以"],"a":0,"e":""},{"q":"就算失败了，___是一次宝贵的经验。","o":["也","才","都","却也不"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["就算很贵，我也要买。","就算很贵，所以我要买。","就算很贵，我就要买。","就算很贵，但是我买了。"],"a":0,"e":""}],"id":18},{"title":"要么……要么……","formula":"要么 A，要么 B","meaning":"Hoặc là A hoặc là B – chỉ có hai lựa chọn, phải chọn một.","usage":"Thường dùng khi đưa ra lựa chọn dứt khoát, khẩu ngữ. Có thể dùng đơn lẻ 要么 = hay là (đề xuất).","position":"Đầu mỗi vế, trước động từ hoặc chủ ngữ.","examples":[["要么你去，要么我去，总得有人去。","Hoặc bạn đi hoặc tôi đi, phải có người đi.","yào me nǐ qù, yào me wǒ qù, zǒng děi yǒu rén qù."],["周末他要么在家看书，要么去健身房。","Cuối tuần anh ấy hoặc ở nhà đọc sách, hoặc đi phòng gym.","zhōu mò tā yào me zài jiā kàn shū, yào me qù jiàn shēn fáng."],["时间不多了，要么我们打车去吧。","Không còn nhiều thời gian, hay là chúng ta bắt taxi đi.","shí jiān bù duō le, yào me wǒ men dǎ chē qù ba."]],"compare":"或者: hoặc (câu trần thuật, không nhấn dứt khoát); 还是: hay (câu hỏi lựa chọn); 要么……要么: hai lựa chọn loại trừ.","errors":"Dùng 要么 trong câu hỏi lựa chọn (✗ 你要么喝茶要么喝咖啡？ → dùng 还是).","ex":[{"q":"___接受这个条件，___放弃合作，你选一个吧。","o":["要么/要么","或者/还是","不是/而是","既/又"],"a":0,"e":"Hai lựa chọn loại trừ."},{"q":"你喝茶___喝咖啡？","o":["要么","还是","或者","要不"],"a":1,"e":"Câu hỏi lựa chọn dùng 还是."},{"q":"他下班后要么看电视，___上网。","o":["要么","还是","而且","以及"],"a":0,"e":""},{"q":"时间来不及了，___我们明天再去吧。","o":["要么","既然","即使","尽管"],"a":0,"e":"要么 = hay là (đề xuất)."},{"q":"Câu nào đúng?","o":["要么你来，还是我去？","要么你来，要么我去。","要么你来，或者我去吗？","你来要么，我去要么。"],"a":1,"e":""}],"id":19},{"title":"要不然 / 否则","formula":"A（điều kiện），要不然/否则 + B（hậu quả）","meaning":"Nếu không thì, bằng không – vế sau nêu hậu quả khi không thực hiện vế trước.","usage":"否则 văn viết; 要不然/要不/不然 khẩu ngữ. Thường đi với 就/会.","position":"Đầu vế sau.","examples":[["快点儿走吧，要不然就赶不上火车了。","Đi nhanh lên, nếu không sẽ lỡ tàu.","kuài diǎn ér zǒu ba, yào bù rán jiù gǎn bù shàng huǒ chē le."],["必须加强管理，否则问题会越来越严重。","Phải tăng cường quản lý, bằng không vấn đề sẽ ngày càng nghiêm trọng.","bì xū jiā qiáng guǎn lǐ, fǒu zé wèn tí huì yuè lái yuè yán zhòng."],["幸亏你提醒我，不然我就忘了。","May mà bạn nhắc, không thì tôi quên mất.","xìng kuī nǐ tí xǐng wǒ, bù rán wǒ jiù wàng le."]],"compare":"否则 = 要不然; 要么 là lựa chọn; 不然 thường đi với 幸亏.","errors":"Đặt 否则 ở vế trước; dịch 'nếu không' thành 如果不 trong mọi trường hợp làm câu nặng nề.","ex":[{"q":"你最好提前预约，___可能没有位子。","o":["要不然","以便","既然","何况"],"a":0,"e":"Hậu quả nếu không làm."},{"q":"我们必须马上采取措施，___后果不堪设想。","o":["否则","从而","以便","因而"],"a":0,"e":""},{"q":"幸亏带了雨伞，___就被淋湿了。","o":["不然","而且","以免","因此"],"a":0,"e":"幸亏……不然……"},{"q":"'否则' gần nghĩa nhất:","o":["要不然","要么","因此","于是"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["否则你早点儿来，我们就不等了。","你早点儿来，否则我们就不等了。","你早点儿来，否则我们就等你了才。","你早点儿来否则。"],"a":1,"e":""}],"id":20},{"title":"好不容易 / 好容易","formula":"主语 + 好（不）容易 + 才 + 动词","meaning":"Vất vả lắm mới, khó khăn lắm mới – hai dạng có nghĩa giống nhau (ngoại lệ đặc biệt của tiếng Trung).","usage":"Thường đi với 才. Khi làm vị ngữ/định ngữ thì chỉ dùng 好不容易 (这真是好不容易的事 ✗ → 很不容易).","position":"Trước động từ, thường kèm 才.","examples":[["我好不容易才买到这两张演唱会的票。","Tôi vất vả lắm mới mua được hai vé buổi hòa nhạc này.","wǒ hǎo bù róng yì cái mǎi dào zhè liǎng zhāng yǎn chàng huì de piào."],["他找了半天，好容易才找到那家小店。","Anh ấy tìm cả buổi, khó khăn lắm mới tìm thấy cửa hàng nhỏ đó.","tā zhǎo le bàn tiān, hǎo róng yì cái zhǎo dào nà jiā xiǎo diàn."],["好不容易盼到了放假，结果又下雨了。","Mong mãi mới đến kỳ nghỉ, rốt cuộc lại mưa.","hǎo bù róng yì pàn dào le fàng jià, jié guǒ yòu xià yǔ le."]],"compare":"好不 + tính từ thường = rất (好不热闹 = 好热闹), nhưng 好不容易 = 好容易 = rất khó.","errors":"Hiểu 好容易 là 'rất dễ' – đây là bẫy thường gặp trong đề thi.","ex":[{"q":"我___才说服他参加比赛。","o":["好不容易","不容易好","很容易","容易好"],"a":0,"e":""},{"q":"'我好容易才找到工作' nghĩa là:","o":["Tôi tìm việc rất dễ","Tôi vất vả lắm mới tìm được việc","Tôi không tìm được việc","Tôi không muốn tìm việc"],"a":1,"e":"好容易 = 好不容易."},{"q":"好不容易等到周末，他___生病了。","o":["却","才","就是","都"],"a":0,"e":"Kết quả trái mong đợi."},{"q":"他们好容易___爬到山顶。","o":["才","就","都","也"],"a":0,"e":"好容易……才……"},{"q":"Câu nào đúng?","o":["这次比赛他很好不容易赢了。","这次比赛他好不容易才赢了。","这次比赛他好容易就赢了吗？","这次比赛好不他容易赢了。"],"a":1,"e":""}],"id":21},{"title":"不禁 / 忍不住","formula":"主语 + 不禁 + 动词（cảm xúc）· 忍不住 + 动词","meaning":"Không kìm được, bất giác – phản ứng cảm xúc tự nhiên do tác động bên ngoài.","usage":"不禁 là phó từ (văn viết), chỉ đứng trước động từ; 忍不住 là động từ (khẩu ngữ), có thể làm vị ngữ độc lập.","position":"Sau chủ ngữ, trước động từ/cụm động từ.","examples":[["看到这感人的场面，大家不禁流下了眼泪。","Thấy cảnh cảm động ấy, mọi người bất giác rơi nước mắt.","kàn dào zhè gǎn rén de chǎng miàn, dà jiā bù jīn liú xià le yǎn lèi."],["听了他的笑话，我忍不住笑了起来。","Nghe chuyện cười của anh ấy, tôi không nhịn được bật cười.","tīng le tā de xiào huà, wǒ rěn bú zhù xiào le qǐ lái."],["他想说什么，可是又忍住了。","Anh ấy muốn nói gì đó nhưng lại kìm lại.","tā xiǎng shuō shén me, kě shì yòu rěn zhù le."]],"compare":"不禁 không đứng một mình (✗ 我不禁了); 忍不住 có thể đứng một mình (我实在忍不住了). 不由得 tương tự 不禁.","errors":"Dùng 不禁 cho hành động có chủ ý (✗ 我不禁去买了一本书).","ex":[{"q":"想起小时候的事，他___笑了。","o":["不禁","不料","不再","不便"],"a":0,"e":"Phản ứng cảm xúc tự nhiên."},{"q":"太好笑了，我实在___了。","o":["不禁","忍不住","不由得","不料"],"a":1,"e":"Đứng độc lập làm vị ngữ: 忍不住."},{"q":"'不禁' gần nghĩa nhất:","o":["不由得","不得不","不至于","不仅"],"a":0,"e":""},{"q":"看到这么美的风景，游客们不禁___。","o":["拿出相机拍了起来","决定明天出发","买了车票","打算回家"],"a":0,"e":"Phản ứng tự nhiên trước cảnh đẹp."},{"q":"Câu nào đúng?","o":["我不禁了。","听到这个好消息，她不禁欢呼起来。","他不禁去银行取钱。","不禁他哭了。"],"a":1,"e":""}],"id":22},{"title":"恰恰 / 恰好 / 正好","formula":"恰恰 + 是/相反（nhấn mạnh）· 恰好/正好 + vừa đúng","meaning":"恰好/正好: vừa may, vừa đúng (thời gian, số lượng, tình huống trùng hợp). 恰恰: chính là, đúng là (nhấn mạnh sự trái ngược với suy nghĩ thông thường).","usage":"恰恰 thường đi với 是、相反、说明. 正好 còn làm tính từ (大小正好), 恰好/恰恰 không.","position":"Phó từ đứng trước động từ/是; 恰好 có thể đứng đầu câu.","examples":[["事实恰恰相反，他并不是一个自私的人。","Sự thật hoàn toàn ngược lại, anh ấy không phải người ích kỷ.","shì shí qià qià xiāng fǎn, tā bìng bú shì yí gè zì sī de rén."],["我到车站的时候，车恰好开过来。","Lúc tôi đến bến, xe vừa đúng chạy tới.","wǒ dào chē zhàn de shí hòu, chē qià hǎo kāi guò lái."],["这双鞋我穿正好。","Đôi giày này tôi đi vừa khít.","zhè shuāng xié wǒ chuān zhèng hǎo."]],"compare":"Bẫy đề thi: 正好 làm vị ngữ được (大小正好), 恰恰 không; 恰恰 dùng để phản bác.","errors":"Dùng 恰恰 làm vị ngữ (✗ 这件衣服恰恰); dùng 恰好 cho phản bác.","ex":[{"q":"你以为他会生气，___相反，他非常高兴。","o":["恰恰","恰好","正好","刚好"],"a":0,"e":"Nhấn mạnh trái ngược."},{"q":"这件衣服大小___，就买它吧。","o":["恰恰","正好","恰巧是","恰当"],"a":1,"e":"正好 làm vị ngữ."},{"q":"我正要给他打电话，___他就来了。","o":["恰好","恰恰","恰当","适当"],"a":0,"e":"Trùng hợp."},{"q":"你说的缺点，___是他的优点。","o":["恰恰","正好的","恰当","适合"],"a":0,"e":"恰恰是 = chính là."},{"q":"Câu nào đúng?","o":["这个房间的大小恰恰。","这个房间的大小正好。","这个房间恰好的大小。","大小恰恰是好的这个房间。"],"a":1,"e":""}],"id":23},{"title":"照样 / 依然 / 仍然","formula":"主语 + 照样/依然/仍然 + 动词/形容词","meaning":"Vẫn như cũ, vẫn vậy – tình trạng không thay đổi dù điều kiện đã khác.","usage":"照样 khẩu ngữ, nhấn 'dù có trở ngại vẫn làm như thường'; 依然 văn viết, thường đi với tính từ; 仍然 trung tính.","position":"Sau chủ ngữ, trước động từ/tính từ.","examples":[["虽然下着大雨，他照样去上班了。","Dù mưa to, anh ấy vẫn đi làm như thường.","suī rán xià zhe dà yǔ, tā zhào yàng qù shàng bān le."],["十年过去了，这里的风景依然那么美。","Mười năm trôi qua, phong cảnh nơi đây vẫn đẹp như vậy.","shí nián guò qù le, zhè lǐ de fēng jǐng yī rán nà me měi."],["医生说了很多次，他仍然不愿意戒烟。","Bác sĩ nói nhiều lần, anh ấy vẫn không chịu bỏ thuốc.","yī shēng shuō le hěn duō cì, tā réng rán bù yuàn yì jiè yān."]],"compare":"照样 còn là động từ 'làm theo mẫu' (照样画一张). 仍然 có thể đi với 是; 依然 hay đi với tính từ miêu tả.","errors":"Đặt 仍然 trước chủ ngữ (✗ 仍然他不来).","ex":[{"q":"没有老师的指导，他___学得很好。","o":["照样","依照","按照","照常地"],"a":0,"e":"Vẫn như thường."},{"q":"多年不见，她___那么年轻漂亮。","o":["依然","依照","依靠","依赖"],"a":0,"e":"Văn viết + tính từ."},{"q":"我们劝了他半天，他___坚持自己的意见。","o":["仍然","居然","果然","忽然"],"a":0,"e":""},{"q":"'照样' trong câu '停电了，商店照样营业' nghĩa là:","o":["Vẫn như thường","Theo mẫu","Đột nhiên","Quả nhiên"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["仍然他不同意。","他仍然不同意。","他不同意仍然。","他仍然地不同意吗了。"],"a":1,"e":""}],"id":24},{"title":"以……为……","formula":"以 + A + 为 + B","meaning":"Lấy A làm B, coi A là B – cấu trúc văn viết rất hay gặp trong HSK 6.","usage":"Biến thể: 以……为主（lấy... làm chính）、以……为例（lấy... làm ví dụ）、以……为荣（lấy... làm vinh）、以……为中心.","position":"Làm trạng ngữ hoặc vị ngữ trong câu.","examples":[["这家餐厅以川菜为主，也有一些粤菜。","Nhà hàng này chủ yếu là món Tứ Xuyên, cũng có vài món Quảng Đông.","zhè jiā cān tīng yǐ chuān cài wéi zhǔ, yě yǒu yī xiē yuè cài."],["我们以这次比赛为例，分析一下失败的原因。","Chúng ta lấy cuộc thi lần này làm ví dụ, phân tích nguyên nhân thất bại.","wǒ men yǐ zhè cì bǐ sài wèi lì, fēn xī yī xià shī bài de yuán yīn."],["父母一直以儿子为荣。","Bố mẹ luôn lấy con trai làm niềm tự hào.","fù mǔ yì zhí yǐ ér zi wèi róng."]],"compare":"把 A 当作 B: khẩu ngữ; 以 A 为 B: văn viết. 作为: với tư cách là.","errors":"Thay 为 bằng 是 (✗ 以学生是主); quên 为 khi dùng 以……为主.","ex":[{"q":"这次活动的参加者___大学生___主。","o":["以/为","把/当","对/来说","在/下"],"a":0,"e":"以……为主."},{"q":"下面我们以中国___例，说明这个问题。","o":["为","是","作","成"],"a":0,"e":"以……为例."},{"q":"'以……为荣' nghĩa là:","o":["Lấy... làm vinh dự","Lấy... làm chính","Lấy... làm ví dụ","Lấy... làm trung tâm"],"a":0,"e":""},{"q":"我们的工作要以顾客___中心。","o":["为","是","把","被"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["这个城市以旅游业是主。","这个城市以旅游业为主。","这个城市把旅游业为主。","以这个城市为旅游业主。"],"a":1,"e":""}],"id":25},{"title":"对……而言 / 就……而言","formula":"对（于）+ đối tượng + 而言/来说 · 就 + phương diện + 而言/来说","meaning":"Đối với (ai đó) mà nói / Xét về (phương diện) mà nói – giới hạn góc nhìn của nhận định.","usage":"而言 văn viết, 来说 khẩu ngữ. 对……而言 nói về đối tượng chịu ảnh hưởng; 就……而言 nói về phương diện xem xét.","position":"Đầu câu, ngăn cách bằng dấu phẩy.","examples":[["对年轻人而言，最重要的是不断学习。","Đối với người trẻ, quan trọng nhất là không ngừng học hỏi.","duì nián qīng rén ér yán, zuì zhòng yào de shì bù duàn xué xí."],["就质量而言，这款手机比那款好得多。","Xét về chất lượng, chiếc điện thoại này tốt hơn nhiều so với chiếc kia.","jiù zhì liàng ér yán, zhè kuǎn shǒu jī bǐ nà kuǎn hǎo dé duō."],["对我来说，家庭比工作更重要。","Với tôi, gia đình quan trọng hơn công việc.","duì wǒ lái shuō, jiā tíng bǐ gōng zuò gèng zhòng yào."]],"compare":"对……来说 = 对……而言 (đối tượng). 就……而言 (phương diện). 在……看来: theo cách nhìn của ai.","errors":"Thiếu 而言/来说 (✗ 对我，这很重要 → 对我来说); dùng 对 cho phương diện (✗ 对价格而言 nên là 就价格而言).","ex":[{"q":"___学生而言，考试压力很大。","o":["对","就","在","由"],"a":0,"e":"Đối tượng: 对……而言."},{"q":"___价格而言，这家店比较便宜。","o":["对","就","把","被"],"a":1,"e":"Phương diện: 就……而言."},{"q":"对很多人___，买房是一生中最大的一笔开支。","o":["来说","而说","看来","说来"],"a":0,"e":""},{"q":"'就……而言' dùng để:","o":["Nêu phương diện xem xét","Nêu nguyên nhân","Nêu mục đích","Nêu thời gian"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["对我，这件事很重要。","对我来说，这件事很重要。","对我而，这件事很重要。","我对来说这件事很重要。"],"a":1,"e":""}],"id":26},{"title":"在……下","formula":"在 + (的) + 帮助/支持/影响/领导/条件 + 下","meaning":"Dưới (sự giúp đỡ / ảnh hưởng / điều kiện) của... – nêu điều kiện, hoàn cảnh dẫn đến kết quả.","usage":"Danh từ ở giữa thường là 帮助、支持、指导、影响、压力、条件、情况. Cụm này làm trạng ngữ đầu câu.","position":"Đầu câu hoặc sau chủ ngữ.","examples":[["在老师的帮助下，他的成绩提高得很快。","Dưới sự giúp đỡ của thầy, thành tích của cậu ấy tiến bộ rất nhanh.","zài lǎo shī de bāng zhù xià, tā de chéng jì tí gāo dé hěn kuài."],["在这种情况下，我们只能改变计划。","Trong tình huống này, chúng ta chỉ có thể thay đổi kế hoạch.","zài zhè zhǒng qíng kuàng xià, wǒ men zhǐ néng gǎi biàn jì huà."],["在父母的影响下，她从小就爱上了音乐。","Dưới ảnh hưởng của bố mẹ, cô ấy yêu âm nhạc từ nhỏ.","zài fù mǔ de yǐng xiǎng xià, tā cóng xiǎo jiù ài shàng le yīn yuè."]],"compare":"在……中: trong quá trình (在学习中); 在……上: về mặt (在工作上). 在……下 chỉ điều kiện tác động.","errors":"Dịch 'dưới sự' thành 在……的下面 (✗); quên 下.","ex":[{"q":"在大家的支持___，这个项目终于完成了。","o":["下","中","上","里"],"a":0,"e":""},{"q":"___这种条件下，很难做出好成绩。","o":["在","从","对","把"],"a":0,"e":""},{"q":"在学习___，我们遇到了很多困难。（trong quá trình）","o":["下","中","上","后"],"a":1,"e":"Quá trình: 在……中."},{"q":"在工作___，他是我的老师。（về mặt）","o":["下","上","中间","里面"],"a":1,"e":"Về mặt: 在……上."},{"q":"Câu nào đúng?","o":["在医生的治疗的下面，他康复了。","在医生的治疗下，他康复了。","在医生下的治疗，他康复了。","医生的在治疗下，他康复了。"],"a":1,"e":""}],"id":27},{"title":"由","formula":"由 + người/đơn vị + 负责/决定/组成 · 由 A 组成","meaning":"由 = do (ai làm) / từ (cái gì cấu thành) – nhấn mạnh chủ thể thực hiện hoặc thành phần cấu tạo.","usage":"由……负责/主持/决定 (do ai phụ trách); 由……组成/构成 (gồm có); 由……引起 (do... gây ra); 由此可见 (từ đó có thể thấy).","position":"Trước động từ, làm trạng ngữ.","examples":[["这次会议由王经理主持。","Cuộc họp lần này do giám đốc Vương chủ trì.","zhè cì huì yì yóu wáng jīng lǐ zhǔ chí."],["我们的团队由五名工程师组成。","Đội của chúng tôi gồm năm kỹ sư.","wǒ men de tuán duì yóu wǔ míng gōng chéng shī zǔ chéng."],["这场火灾是由电线老化引起的。","Vụ cháy này do dây điện cũ gây ra.","zhè chǎng huǒ zāi shì yóu diàn xiàn lǎo huà yǐn qǐ de."]],"compare":"被 nhấn mạnh người chịu tác động (thường tiêu cực); 由 nhấn mạnh trách nhiệm/chủ thể, trung tính. 从 chỉ điểm xuất phát.","errors":"Dùng 被……组成 (✗ 被五个人组成 → 由五个人组成); dùng 从 thay 由 với 负责.","ex":[{"q":"这个问题___我来解决吧。","o":["由","被","从","对"],"a":0,"e":"Do ai phụ trách."},{"q":"水___氢和氧组成。","o":["由","被","从","把"],"a":0,"e":"由……组成."},{"q":"这次事故是___司机疲劳驾驶引起的。","o":["由","把","对","给"],"a":0,"e":"由……引起."},{"q":"___此可见，坚持是成功的关键。","o":["由","从而","因而","以"],"a":0,"e":"由此可见."},{"q":"Câu nào đúng?","o":["委员会被七个人组成。","委员会由七个人组成。","委员会从七个人组成。","委员会把七个人组成。"],"a":1,"e":""}],"id":28},{"title":"之所以……是因为……","formula":"（主语）之所以 + kết quả，是因为/是由于 + nguyên nhân","meaning":"Sở dĩ ... là vì ... – nêu kết quả trước, nhấn mạnh nguyên nhân ở sau.","usage":"Văn viết, nghị luận. Đảo trật tự so với 因为……所以 để nhấn mạnh nguyên nhân.","position":"之所以 sau chủ ngữ vế 1; 是因为 đầu vế 2.","examples":[["他之所以能成功，是因为他从不放弃。","Sở dĩ anh ấy thành công là vì anh ấy không bao giờ bỏ cuộc.","tā zhī suǒ yǐ néng chéng gōng, shì yīn wèi tā cóng bù fàng qì."],["这家店之所以受欢迎，是由于服务特别好。","Cửa hàng này sở dĩ được ưa chuộng là do phục vụ đặc biệt tốt.","zhè jiā diàn zhī suǒ yǐ shòu huān yíng, shì yóu yú fú wù tè bié hǎo."],["我之所以选择这个专业，是因为对它很感兴趣。","Tôi sở dĩ chọn chuyên ngành này là vì rất hứng thú với nó.","wǒ zhī suǒ yǐ xuǎn zé zhè ge zhuān yè, shì yīn wèi duì tā hěn gǎn xìng qù."]],"compare":"因为……所以: nguyên nhân trước; 之所以……是因为: kết quả trước, nhấn nguyên nhân. Không dùng 之所以……所以.","errors":"Ghép 之所以……所以 (✗); thiếu 是 trước 因为.","ex":[{"q":"他___迟到，是因为路上堵车了。","o":["之所以","所以","因此","因而"],"a":0,"e":""},{"q":"我之所以喜欢这座城市，___这里的人很热情。","o":["是因为","所以","因此","于是"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["之所以他成功，所以很努力。","他之所以成功，是因为很努力。","他之所以成功，因此很努力。","他所以成功，之是因为努力。"],"a":1,"e":""},{"q":"'之所以……是因为……' nhấn mạnh:","o":["Nguyên nhân","Kết quả","Thời gian","Điều kiện"],"a":0,"e":""},{"q":"这部电影之所以感人，___它讲的是真实的故事。","o":["是由于","由于是","所以是","于是"],"a":0,"e":""}],"id":29},{"title":"并非 / 并不 / 并没有","formula":"主语 + 并 + 不/没（有）/非 + ……","meaning":"Thật ra không, hoàn toàn không – phủ định nhấn mạnh, bác bỏ một suy nghĩ hay cách hiểu sai.","usage":"并 đặt trước 不/没/非 để nhấn mạnh 'sự thật không như bạn nghĩ'. 并非 = 并不是 (văn viết).","position":"Sau chủ ngữ, trước từ phủ định.","examples":[["学习汉语并不像你想象的那么难。","Học tiếng Trung thật ra không khó như bạn tưởng.","xué xí hàn yǔ bìng bù xiàng nǐ xiǎng xiàng de nà me nán."],["成功并非偶然，而是长期努力的结果。","Thành công không phải ngẫu nhiên, mà là kết quả của nỗ lực lâu dài.","chéng gōng bìng fēi ǒu rán, ér shì cháng qī nǔ lì de jié guǒ."],["我并没有说过这样的话。","Tôi hoàn toàn không hề nói câu đó.","wǒ bìng méi yǒu shuō guò zhè yàng de huà."]],"compare":"并 + phủ định thường đi với 而是 (không phải A mà là B). 不是……而是 trung tính hơn.","errors":"Dùng 并 trong câu khẳng định (✗ 他并很好); đặt 并 sau 不 (✗ 不并).","ex":[{"q":"他___不是不想帮你，而是实在没时间。","o":["并","也","就","才"],"a":0,"e":""},{"q":"这件事___你想的那样简单。","o":["并非","并是","不并","非并"],"a":0,"e":""},{"q":"我___没有拿你的书，你再找找吧。","o":["并","都","才","就"],"a":0,"e":""},{"q":"'并非' = ?","o":["并不是","并且","而且","并列"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["这个问题并很难。","这个问题并不难。","这个问题不并难。","并这个问题不难。"],"a":1,"e":""}],"id":30},{"title":"鉴于 / 基于","formula":"鉴于 + tình hình，（主语）+ quyết định · 基于 + cơ sở/lý do","meaning":"鉴于: xét thấy, căn cứ vào tình hình (thường dẫn đến quyết định). 基于: dựa trên (cơ sở, nguyên tắc, lý do).","usage":"Văn viết trang trọng, dùng trong thông báo, báo cáo, nghị luận. 鉴于 đứng đầu câu; 基于 có thể đứng đầu câu hoặc làm định ngữ (基于事实的判断).","position":"Đầu câu, ngăn cách bằng dấu phẩy.","examples":[["鉴于天气原因，原定的户外活动改到下周举行。","Xét thấy lý do thời tiết, hoạt động ngoài trời dự định sẽ dời sang tuần sau.","jiàn yú tiān qì yuán yīn, yuán dìng de hù wài huó dòng gǎi dào xià zhōu jǔ xíng."],["基于以上分析，我们认为这个方案是可行的。","Dựa trên phân tích trên, chúng tôi cho rằng phương án này khả thi.","jī yú yǐ shàng fēn xī, wǒ men rèn wéi zhè ge fāng àn shì kě xíng de."],["鉴于他的突出表现，公司决定提升他为部门经理。","Xét thấy thành tích nổi bật của anh ấy, công ty quyết định thăng chức anh lên trưởng phòng.","jiàn yú tā de tū chū biǎo xiàn, gōng sī jué dìng tí shēng tā wèi bù mén jīng lǐ."]],"compare":"由于: do, bởi vì (nguyên nhân chung); 鉴于: nhấn mạnh việc cân nhắc tình hình rồi quyết định; 根据: căn cứ theo (tài liệu, quy định).","errors":"Dùng 鉴于 trong khẩu ngữ đời thường; đặt 鉴于 ở vế sau.","ex":[{"q":"___目前的情况，我们决定暂停这个项目。","o":["鉴于","以免","以便","从而"],"a":0,"e":""},{"q":"这个结论是___大量实验数据得出的。","o":["基于","鉴于","以至","由于是"],"a":0,"e":"Dựa trên cơ sở dữ liệu."},{"q":"'鉴于' thường dùng trong:","o":["Văn bản trang trọng","Nói chuyện với bạn bè","Thơ ca","Tiếng lóng"],"a":0,"e":""},{"q":"___安全考虑，请乘客不要靠近车门。","o":["出于","以免","以便","免得"],"a":0,"e":"出于……考虑 – xuất phát từ cân nhắc."},{"q":"Câu nào đúng?","o":["比赛取消了，鉴于下大雨。","鉴于连日大雨，比赛取消了。","鉴于比赛，连日大雨取消。","比赛鉴于取消了大雨。"],"a":1,"e":""}],"id":31},{"title":"截至 / 截止","formula":"截至 + thời điểm（tính đến）· 截止（到）+ thời điểm / A + 截止（kết thúc）","meaning":"截至: tính đến (thời điểm), sau đó là số liệu thống kê. 截止: hạn chót, kết thúc (thường đứng sau thời gian hoặc dùng 截止到/截止日期).","usage":"截至 phải có tân ngữ thời gian ngay sau; 截止 thường là động từ nội động (报名于5月1日截止) hoặc 截止到.","position":"截至 đầu câu; 截止 làm vị ngữ ở cuối câu hoặc định ngữ (截止日期).","examples":[["截至去年年底，该市人口已超过一千万。","Tính đến cuối năm ngoái, dân số thành phố đã vượt mười triệu.","jié zhì qù nián nián dǐ, gāi shì rén kǒu yǐ chāo guò yī qiān wàn."],["报名时间到本月二十号截止。","Thời gian đăng ký kết thúc vào ngày 20 tháng này.","bào míng shí jiān dào běn yuè èr shí hào jié zhǐ."],["论文的截止日期是下周五。","Hạn chót nộp luận văn là thứ Sáu tuần sau.","lùn wén de jié zhǐ rì qī shì xià zhōu wǔ."]],"compare":"截至 + thời gian + số liệu (tính đến); 截止 = dừng lại vào lúc. 截至 không đứng cuối câu.","errors":"Viết 报名截至五月 ở cuối câu (✗ nên dùng 截止); nhầm chữ 至/止.","ex":[{"q":"___目前，已有三百人报名。","o":["截至","截止","终止","停止"],"a":0,"e":"Tính đến + số liệu."},{"q":"比赛报名将于下周一___。","o":["截止","截至","以至","直至于"],"a":0,"e":"Kết thúc."},{"q":"申请的___日期是6月30日。","o":["截止","截至","截然","截住"],"a":0,"e":"截止日期."},{"q":"___2025年底，该公司员工已达五千人。","o":["截至","截止于是","截然","停止"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["投稿日期10月1日截至。","投稿日期到10月1日截止。","截止到目前，参加者是一百人的截止。","投稿截至。"],"a":1,"e":""}],"id":32},{"title":"与……相比 / 相比之下","formula":"与/和/跟 + A + 相比，B…… · ……。相比之下，……","meaning":"So với A thì B... / Tương phản lại, so ra thì... – dùng để so sánh trong văn nghị luận.","usage":"与……相比 làm trạng ngữ đầu câu; 相比之下 nối hai câu, đứng đầu câu sau. 与……相比 có thể đứng sau chủ ngữ.","position":"Đầu câu hoặc sau chủ ngữ.","examples":[["与十年前相比，人们的生活水平有了很大提高。","So với mười năm trước, mức sống của người dân đã nâng cao rất nhiều.","yǔ shí nián qián xiāng bǐ, rén men de shēng huó shuǐ píng yǒu le hěn dà tí gāo."],["城市交通拥挤，空气污染严重。相比之下，农村的环境要好得多。","Thành phố giao thông tắc nghẽn, ô nhiễm nặng. So ra, môi trường nông thôn tốt hơn nhiều.","chéng shì jiāo tōng yōng jǐ, kōng qì wū rǎn yán zhòng. xiāng bǐ zhī xià, nóng cūn de huán jìng yào hǎo dé duō."],["这款产品与同类产品相比，价格更有优势。","Sản phẩm này so với sản phẩm cùng loại có lợi thế về giá hơn.","zhè kuǎn chǎn pǐn yǔ tóng lèi chǎn pǐn xiāng bǐ, jià gé gèng yǒu yōu shì."]],"compare":"比 dùng trong câu so sánh trực tiếp (A比B+tính từ); 与……相比 trang trọng, làm trạng ngữ, sau đó không dùng 比 nữa.","errors":"Dùng cả 与……相比 và 比 trong một câu (✗ 与去年相比，今年比去年好).","ex":[{"q":"___去年相比，今年的销售额增长了20%。","o":["与","比","对","由"],"a":0,"e":""},{"q":"南方冬天很冷，___，北方有暖气，屋里很暖和。","o":["相比之下","总而言之","由此可见","换句话说"],"a":0,"e":""},{"q":"这个城市与其他城市___，物价比较低。","o":["相比","比较的","对比于","比起来是"],"a":0,"e":""},{"q":"'相比之下' dùng để:","o":["So sánh hai sự vật","Nêu kết luận","Nêu ví dụ","Nêu nguyên nhân"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["与过去相比，现在比过去方便多了。","与过去相比，现在方便多了。","与过去比相，现在方便多了。","过去与相比现在方便。"],"a":1,"e":""}],"id":33},{"title":"随着……","formula":"随着 + sự thay đổi，（主语）+ cũng thay đổi theo","meaning":"Cùng với, theo đà (sự phát triển, thay đổi) của... – nêu nguyên nhân/điều kiện biến đổi.","usage":"Danh từ sau 随着 thường là cụm chỉ sự thay đổi: 经济的发展、科技的进步、年龄的增长、时间的推移. Vế sau thường có 越来越、逐渐、也.","position":"Đầu câu.","examples":[["随着经济的发展，人们越来越重视健康。","Cùng với sự phát triển kinh tế, con người ngày càng coi trọng sức khỏe.","suí zhe jīng jì de fā zhǎn, rén men yuè lái yuè zhòng shì jiàn kāng."],["随着年龄的增长，他变得越来越成熟了。","Theo tuổi tác tăng lên, anh ấy trở nên ngày càng chín chắn.","suí zhe nián líng de zēng zhǎng, tā biàn dé yuè lái yuè chéng shú le."],["随着互联网的普及，网上购物已成为一种生活方式。","Cùng với sự phổ cập của Internet, mua sắm trực tuyến đã trở thành một lối sống.","suí zhe hù lián wǎng de pǔ jí, wǎng shàng gòu wù yǐ chéng wéi yī zhǒng shēng huó fāng shì."]],"compare":"跟着: đi theo (động tác cụ thể); 随着: theo đà thay đổi (trừu tượng).","errors":"Thiếu danh từ chỉ biến đổi (✗ 随着经济，人们…… → 随着经济的发展); dùng 随着 cho sự kiện một lần.","ex":[{"q":"___科技的进步，我们的生活越来越方便。","o":["随着","跟着","沿着","接着"],"a":0,"e":""},{"q":"随着时间的___，他慢慢忘记了这件事。","o":["推移","发生","出现","开始"],"a":0,"e":""},{"q":"随着生活水平的提高，人们对教育的要求___。","o":["也越来越高","也很高了吗","就高","才高"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["随着经济，城市变大了。","随着经济的发展，城市变大了。","随着经济发展了，城市变大。","城市随着变大经济的发展。"],"a":1,"e":""},{"q":"'随着' gần nghĩa nhất:","o":["伴随着……的变化","沿着","跟随某人走","接下来"],"a":0,"e":""}],"id":34},{"title":"从而 / 进而","formula":"A（phương pháp/nguyên nhân），从而 + B（kết quả/mục đích）· A，进而 + B（bước tiếp theo, cao hơn）","meaning":"从而: từ đó, nhờ đó (kết quả đạt được nhờ A). 进而: tiến thêm một bước, rồi tiếp đó (B ở mức cao hơn A).","usage":"Văn viết, nghị luận. Vế sau thường lược chủ ngữ (cùng chủ ngữ với vế trước).","position":"Đầu vế sau.","examples":[["公司改进了生产技术，从而降低了成本。","Công ty cải tiến kỹ thuật sản xuất, nhờ đó giảm được chi phí.","gōng sī gǎi jìn le shēng chǎn jì shù, cóng ér jiàng dī le chéng běn."],["先了解客户的需求，进而提供个性化的服务。","Trước hết tìm hiểu nhu cầu khách hàng, tiến thêm bước nữa là cung cấp dịch vụ cá nhân hóa.","xiān liǎo jiě kè hù de xū qiú, jìn ér tí gōng gè xìng huà de fú wù."],["多读书可以开阔视野，从而提高写作水平。","Đọc nhiều sách có thể mở rộng tầm nhìn, từ đó nâng cao trình độ viết.","duō dú shū kě yǐ kāi kuò shì yě, cóng ér tí gāo xiě zuò shuǐ píng."]],"compare":"因此/所以: kết quả chung; 从而: kết quả đạt được nhờ phương pháp ở vế trước, vế sau không có chủ ngữ mới; 以便: mục đích.","errors":"Đặt chủ ngữ mới sau 从而 (✗ 从而我们……); dùng 从而 ở đầu câu đầu tiên.","ex":[{"q":"他每天坚持锻炼，___增强了体质。","o":["从而","以免","何况","况且"],"a":0,"e":"Kết quả nhờ phương pháp."},{"q":"我们要先发现问题，___找到解决问题的办法。","o":["进而","以免","况且","何况"],"a":0,"e":"Bước tiếp theo."},{"q":"政府加大了投入，___改善了农村的教育条件。","o":["从而","否则","尽管","即使"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["从而他努力学习，提高了成绩。","他努力学习，从而提高了成绩。","他从而努力学习，成绩提高。","他努力学习，从而他们提高了。"],"a":1,"e":""},{"q":"'从而' gần nghĩa nhất:","o":["因此（nhờ đó）","以免","尽管","即使"],"a":0,"e":""}],"id":35},{"title":"不仅仅 / 不光 / 不单","formula":"不仅仅/不光/不单 + A，还/也 + B","meaning":"Không chỉ (đơn thuần) là A, mà còn B – mở rộng phạm vi, nhấn mạnh hơn 不仅.","usage":"不仅仅 nhấn mạnh 'không chỉ đơn giản'; 不光/不单 khẩu ngữ. Có thể đi với 是 (不仅仅是……).","position":"Trước động từ hoặc trước chủ ngữ.","examples":[["教育不仅仅是传授知识，更重要的是培养能力。","Giáo dục không chỉ đơn thuần là truyền thụ kiến thức, quan trọng hơn là bồi dưỡng năng lực.","jiào yù bù jǐn jǐn shì chuán shòu zhī shí, gèng zhòng yào de shì péi yǎng néng lì."],["不光年轻人，老年人也开始用手机支付了。","Không chỉ người trẻ, người già cũng bắt đầu dùng điện thoại thanh toán.","bù guāng nián qīng rén, lǎo nián rén yě kāi shǐ yòng shǒu jī zhī fù le."],["这不单是你一个人的问题，大家都有责任。","Đây không chỉ là vấn đề của một mình bạn, mọi người đều có trách nhiệm.","zhè bù dān shì nǐ yí gè rén de wèn tí, dà jiā dōu yǒu zé rèn."]],"compare":"不仅仅 nhấn mạnh hơn 不仅; vế sau hay dùng 更 để tăng tiến.","errors":"Dùng 不仅仅……但是 (✗).","ex":[{"q":"旅游___是为了看风景，还可以了解当地文化。","o":["不仅仅","不只是不","仅仅不","不然"],"a":0,"e":""},{"q":"___我，我们全家都喜欢看足球。","o":["不光","不料","不禁","不便"],"a":0,"e":""},{"q":"读书不仅仅是为了考试，___是为了丰富自己。","o":["更","却","才","就"],"a":0,"e":""},{"q":"'不光' khẩu ngữ tương đương:","o":["不仅","不再","不禁","不便"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["这不仅仅是钱的问题，但是还有面子问题。","这不仅仅是钱的问题，还有面子问题。","这仅仅不是钱的问题。","不仅仅这是钱问题而。"],"a":1,"e":""}],"id":36},{"title":"只得 / 只好 / 不得不","formula":"主语 + 只得/只好/不得不 + 动词","meaning":"Đành phải, buộc phải – không còn lựa chọn khác.","usage":"只得 văn viết; 只好 khẩu ngữ; 不得不 nhấn mạnh sự bắt buộc từ hoàn cảnh (phủ định kép).","position":"Sau chủ ngữ, trước động từ.","examples":[["最后一班车已经开走了，我们只得打车回家。","Chuyến xe cuối đã chạy, chúng tôi đành phải bắt taxi về.","zuì hòu yī bān chē yǐ jīng kāi zǒu le, wǒ men zhǐ dé dǎ chē huí jiā."],["因为下雨，运动会只好推迟。","Vì mưa, hội thao đành phải hoãn.","yīn wèi xià yǔ, yùn dòng huì zhǐ hǎo tuī chí."],["为了照顾生病的母亲，他不得不辞掉工作。","Để chăm sóc mẹ ốm, anh ấy buộc phải nghỉ việc.","wèi le zhào gù shēng bìng de mǔ qīn, tā bù dé bù cí diào gōng zuò."]],"compare":"只得 = 只好 về nghĩa; 不得不 nhấn bắt buộc mạnh hơn; 非……不可: nhất định phải (ý chí hoặc tất yếu).","errors":"Viết 不得不 thành 不得 (thiếu 不); đặt 只好 trước chủ ngữ.","ex":[{"q":"电梯坏了，我们___爬楼梯上去。","o":["只得","只顾","只管","只要"],"a":0,"e":""},{"q":"为了赶上进度，大家___加班。","o":["不得不","不至于","不禁","不料"],"a":0,"e":""},{"q":"'只得' gần nghĩa nhất:","o":["只好","只顾","只管","只是"],"a":0,"e":""},{"q":"买不到票，他___放弃了这次旅行。","o":["只好","只要","只有","只能是"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["只好我们回家了。","我们只好回家了。","我们回家只好了。","我们只好的回家。"],"a":1,"e":""}],"id":37},{"title":"以至于 / 以致","formula":"A，以至于/以致 + B（kết quả, mức độ）","meaning":"Đến nỗi, đến mức – A dẫn đến kết quả B (thường là mức độ cao). 以致 thường dẫn đến kết quả xấu.","usage":"Văn viết. 以至于 kết quả trung tính hoặc xấu; 以致 thường tiêu cực. 以至 còn nghĩa 'cho đến' (从小学以至大学).","position":"Đầu vế sau.","examples":[["他工作太投入了，以至于忘了吃午饭。","Anh ấy quá chú tâm làm việc đến nỗi quên ăn trưa.","tā gōng zuò tài tóu rù le, yǐ zhì yú wàng le chī wǔ fàn."],["他平时不注意身体，以致病倒了。","Anh ấy ngày thường không chú ý sức khỏe, đến nỗi đổ bệnh.","tā píng shí bù zhù yì shēn tǐ, yǐ zhì bìng dào le."],["这个故事太感人了，以至于很多观众都哭了。","Câu chuyện cảm động đến nỗi nhiều khán giả đã khóc.","zhè ge gù shì tài gǎn rén le, yǐ zhì yú hěn duō guān zhòng dōu kū le."]],"compare":"以至于 (đến nỗi – kết quả) ≠ 以免 (để tránh – mục đích) ≠ 不至于 (không đến nỗi).","errors":"Nhầm 以致 với 以至 khi nói phạm vi; dùng 以致 cho kết quả tốt.","ex":[{"q":"他说得太快了，___大家都没听清楚。","o":["以至于","以免","以便","免得"],"a":0,"e":"Kết quả."},{"q":"由于管理不善，___公司损失严重。","o":["以致","以便","以免","从而能"],"a":0,"e":"Kết quả xấu."},{"q":"'以至于' khác '以免' ở chỗ:","o":["以至于 nêu kết quả, 以免 nêu mục đích tránh","Giống nhau hoàn toàn","以至于 nêu mục đích","以免 nêu kết quả"],"a":0,"e":""},{"q":"雨下得很大，___路上一个行人都没有。","o":["以至于","不至于","至于","以便"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["他太紧张了，以至于说不出话来。","他太紧张了，以免说不出话来。","他太紧张了，不至于说不出话来了吗。","以至于他太紧张说话。"],"a":0,"e":""}],"id":38},{"title":"一方面……另一方面……","formula":"一方面 A，另一方面 B","meaning":"Một mặt A, mặt khác B – trình bày hai khía cạnh của một vấn đề (cùng chiều hoặc trái chiều).","usage":"Rất hữu ích trong văn nghị luận và nói. Vế sau thường thêm 也/又/还.","position":"Đầu mỗi vế.","examples":[["一方面，网络让我们的生活更方便；另一方面，它也带来了许多问题。","Một mặt, mạng internet làm cuộc sống tiện lợi hơn; mặt khác, nó cũng mang đến nhiều vấn đề.","yì fāng miàn, wǎng luò ràng wǒ men de shēng huó gèng fāng biàn; lìng yì fāng miàn, tā yě dài lái le xǔ duō wèn tí."],["他出国留学，一方面是为了学习，另一方面也是为了开阔眼界。","Anh ấy đi du học, một mặt để học tập, mặt khác cũng để mở rộng tầm mắt.","tā chū guó liú xué, yì fāng miàn shì wèi le xué xí, lìng yì fāng miàn yě shì wèi le kāi kuò yǎn jiè."],["我们一方面要发展经济，另一方面要保护环境。","Chúng ta một mặt phải phát triển kinh tế, mặt khác phải bảo vệ môi trường.","wǒ men yì fāng miàn yào fā zhǎn jīng jì, lìng yì fāng miàn yào bǎo hù huán jìng."]],"compare":"首先……其次……: liệt kê theo thứ tự; 一方面……另一方面: hai mặt song song.","errors":"Viết 一方面……一方面 trong văn viết hiện đại (nên dùng 另一方面); quên 也/又.","ex":[{"q":"一方面我很想去，___我又担心没有时间。","o":["另一方面","第二方面","其他方面","别方面"],"a":0,"e":""},{"q":"他学汉语，一方面因为工作需要，另一方面___因为喜欢中国文化。","o":["也是","就是","才是","却不"],"a":0,"e":""},{"q":"'一方面……另一方面……' dùng để:","o":["Trình bày hai khía cạnh","Nêu điều kiện","Nêu giả thiết","So sánh hơn kém"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["一方面要学习，二方面要工作。","一方面要学习，另一方面也要休息。","一方面学习，另方面。","另一方面要学习，一方面要休息才。"],"a":1,"e":""},{"q":"手机一方面方便了沟通，另一方面___减少了面对面的交流。","o":["也","才","都","就是"],"a":0,"e":""}],"id":39},{"title":"总而言之 / 综上所述 / 由此可见","formula":"（Mở đoạn kết）总而言之 / 综上所述，…… · 由此可见，……","meaning":"Tóm lại / Tổng hợp những điều trên / Từ đó có thể thấy – từ nối kết luận trong văn nghị luận.","usage":"综上所述: trang trọng nhất, dùng kết bài luận; 总而言之 / 总之: tóm lại; 由此可见: rút ra kết luận từ dẫn chứng vừa nêu.","position":"Đầu đoạn hoặc đầu câu cuối.","examples":[["综上所述，保护环境是每个人的责任。","Tổng hợp những điều trên, bảo vệ môi trường là trách nhiệm của mỗi người.","zōng shàng suǒ shù, bǎo hù huán jìng shì měi gè rén de zé rèn."],["总而言之，只有不断学习，才能跟上时代的发展。","Tóm lại, chỉ có không ngừng học hỏi mới theo kịp sự phát triển của thời đại.","zǒng ér yán zhī, zhǐ yǒu bù duàn xué xí, cái néng gēn shàng shí dài de fā zhǎn."],["他三次参赛都获得了冠军，由此可见他的实力有多强。","Anh ấy ba lần thi đều giành vô địch, từ đó có thể thấy thực lực mạnh thế nào.","tā sān cì cān sài dōu huò dé le guàn jūn, yóu cǐ kě jiàn tā de shí lì yǒu duō qiáng."]],"compare":"例如/比如: nêu ví dụ; 换句话说: nói cách khác; 总之: tóm lại (khẩu ngữ hơn).","errors":"Dùng 综上所述 khi chưa trình bày luận điểm nào; dùng 由此可见 không có dẫn chứng phía trước.","ex":[{"q":"___，我认为大学生应该多参加社会实践。（kết bài luận）","o":["综上所述","例如","首先","比如说"],"a":0,"e":""},{"q":"他每天只睡五个小时，___，他的工作压力非常大。","o":["由此可见","比如","首先","另外"],"a":0,"e":""},{"q":"'总而言之' gần nghĩa nhất:","o":["总之","例如","然而","此外"],"a":0,"e":""},{"q":"Từ nào thường mở đầu đoạn KẾT của bài nghị luận?","o":["综上所述","首先","例如","一方面"],"a":0,"e":""},{"q":"Câu nào đúng?","o":["由此可见，我们开始讨论吧。","大家都同意了，由此可见这个方案很受欢迎。","综上所述，第一点是……","例如，综上所述。"],"a":1,"e":""}],"id":40},{"title":"毫无 / 丝毫不","formula":"毫无 + danh từ 2 âm tiết（毫无疑问/意义/关系）· 丝毫 + 不/没有 + ……","meaning":"Hoàn toàn không, không một chút nào – phủ định tuyệt đối, văn viết.","usage":"毫无 + danh từ (thường 2 âm tiết): 毫无疑问、毫无意义、毫无准备、毫无关系. 丝毫 đi với 不/没有: 丝毫不差、丝毫没有改变.","position":"毫无 làm vị ngữ hoặc định ngữ; 丝毫 trước 不/没有.","examples":[["毫无疑问，他是这次比赛中表现最好的选手。","Không còn nghi ngờ gì, anh ấy là tuyển thủ thể hiện tốt nhất cuộc thi này.","háo wú yí wèn, tā shì zhè cì bǐ sài zhōng biǎo xiàn zuì hǎo de xuǎn shǒu."],["这种争论毫无意义，我们还是说点儿别的吧。","Tranh luận kiểu này hoàn toàn vô nghĩa, chúng ta nói chuyện khác đi.","zhè zhǒng zhēng lùn háo wú yì yì, wǒ men hái shì shuō diǎn ér bié de ba."],["面对困难，他丝毫没有退缩。","Đối mặt khó khăn, anh ấy không hề lùi bước chút nào.","miàn duì kùn nán, tā sī háo méi yǒu tuì suō."]],"compare":"毫无 = 一点儿也没有 (văn viết); 丝毫 cần từ phủ định đi kèm, 毫无 thì bản thân đã phủ định.","errors":"Viết 毫无没有 (✗ thừa phủ định); dùng 丝毫 mà không có 不/没.","ex":[{"q":"这两件事___关系，你别混在一起。","o":["毫无","丝毫","毫不是","没毫"],"a":0,"e":""},{"q":"他对自己的错误___不在乎。","o":["丝毫","毫无","没有","无毫"],"a":0,"e":"丝毫 + 不."},{"q":"___疑问，这是一个正确的决定。","o":["毫无","丝毫","毫不","没有"],"a":0,"e":"毫无疑问."},{"q":"Câu nào đúng?","o":["他毫无没有经验。","他毫无经验。","他丝毫经验。","他经验毫无没。"],"a":1,"e":""},{"q":"'毫无意义' nghĩa là:","o":["Hoàn toàn vô nghĩa","Rất có ý nghĩa","Hơi có ý nghĩa","Ý nghĩa sâu sắc"],"a":0,"e":""}],"id":41},{"title":"反问句：难道……吗？/ 何必……呢？/ 岂不是……","formula":"难道 + A + 吗？· 何必 + V + 呢？· 岂不是 + A？","meaning":"Câu hỏi tu từ để khẳng định mạnh hơn: 难道……吗 (lẽ nào... sao?) = khẳng định ngược lại; 何必 (cần gì phải) = không cần; 岂不是 (chẳng phải là... sao) = chính là.","usage":"Dùng nhiều trong đọc hiểu và nghị luận để nhấn mạnh quan điểm. Hiểu đúng ý ngầm là kỹ năng then chốt của HSK 6.","position":"难道 sau chủ ngữ hoặc đầu câu; 何必 trước động từ; 岂不是 đầu vế sau.","examples":[["这么简单的道理，难道你不明白吗？","Đạo lý đơn giản thế này, lẽ nào bạn không hiểu? (= bạn phải hiểu)","zhè me jiǎn dān de dào lǐ, nán dào nǐ bù míng bái ma?"],["都是老朋友了，何必这么客气呢？","Đều là bạn cũ cả, cần gì khách sáo thế? (= không cần khách sáo)","dōu shì lǎo péng yǒu le, hé bì zhè me kè qì ne?"],["如果现在放弃，以前的努力岂不是白费了？","Nếu bây giờ bỏ cuộc, chẳng phải công sức trước đây đổ sông đổ biển sao?","rú guǒ xiàn zài fàng qì, yǐ qián de nǔ lì qǐ bù shì bái fèi le?"]],"compare":"不是……吗？cũng là câu hỏi tu từ (chẳng phải... sao?). 何必 = 不必 (văn tu từ).","errors":"Hiểu câu tu từ như câu hỏi thật và trả lời 是/不是; quên 吗/呢 cuối câu.","ex":[{"q":"'难道你不知道吗？' ý người nói là:","o":["Bạn chắc chắn biết","Bạn không biết","Tôi muốn hỏi bạn có biết không","Tôi không biết"],"a":0,"e":""},{"q":"一点儿小事，___生这么大的气呢？","o":["何必","何况","况且","难怪"],"a":0,"e":""},{"q":"你现在才走，___要迟到了？","o":["岂不是","难道是不","何必是","何况是"],"a":0,"e":""},{"q":"'何必' gần nghĩa:","o":["不必","必须","必定","务必"],"a":0,"e":""},{"q":"Câu nào là câu hỏi tu từ?","o":["你吃饭了吗？","难道他会骗你吗？","你几点下班？","这是谁的书？"],"a":1,"e":""}],"id":42},{"title":"双重否定：不得不 / 非……不可 / 不能不 / 没有……不……","formula":"不 + V + 不 · 非 + A + 不可 · 没有 + N + 不 + V","meaning":"Phủ định kép để khẳng định mạnh: 非……不可 (nhất định phải), 不能不 (không thể không), 没有……不…… (không có ai/gì là không...).","usage":"非……不可 có thể biểu thị ý chí (我非去不可) hoặc tất yếu (不听话非吃亏不可). 没有人不知道 = ai cũng biết.","position":"非 trước động từ; 不可 cuối câu.","examples":[["这件事很重要，我非亲自去一趟不可。","Việc này rất quan trọng, tôi nhất định phải tự đi một chuyến.","zhè jiàn shì hěn zhòng yào, wǒ fēi qīn zì qù yī tàng bù kě."],["在这个城市，没有人不知道这家老字号。","Ở thành phố này, không ai là không biết cửa hiệu lâu đời này.","zài zhè ge chéng shì, méi yǒu rén bù zhī dào zhè jiā lǎo zì hào."],["他的话很有道理，我们不能不认真考虑。","Lời anh ấy rất có lý, chúng ta không thể không cân nhắc kỹ.","tā de huà hěn yǒu dào lǐ, wǒ men bù néng bù rèn zhēn kǎo lǜ."]],"compare":"非……不可 mạnh hơn 必须; 不得不 nhấn bị ép bởi hoàn cảnh; 不能不 nhấn cần thiết.","errors":"Bỏ 不可 trong 非……不可 ở văn viết; hiểu nhầm phủ định kép thành phủ định.","ex":[{"q":"你这样不听医生的话，___生病不可。","o":["非","不","没","别"],"a":0,"e":"非……不可."},{"q":"'没有人不喜欢他' nghĩa là:","o":["Ai cũng thích anh ấy","Không ai thích anh ấy","Ít người thích anh ấy","Anh ấy không thích ai"],"a":0,"e":""},{"q":"这个机会太难得了，我们___抓住。","o":["不能不","不至于","不禁","不料"],"a":0,"e":""},{"q":"我非要把这件事弄清楚___。","o":["不可","不行吗","不要","不必"],"a":0,"e":""},{"q":"Câu nào mang nghĩa khẳng định mạnh?","o":["他不一定来。","他非来不可。","他不来。","他可能不来。"],"a":1,"e":""}],"id":43},{"title":"关于 / 对于 / 有关","formula":"关于 + chủ đề · 对于 + đối tượng（+ thái độ/tác động）· 有关 + N / 与……有关","meaning":"关于: về (nội dung, chủ đề); 对于: đối với (đối tượng của thái độ, cách xử lý); 有关: liên quan đến.","usage":"关于 có thể làm tiêu đề (关于环境保护); 对于 không. 对于 có thể đứng sau chủ ngữ, 关于 thường chỉ đứng đầu câu. 与/跟……有关: có liên quan với.","position":"Đầu câu hoặc làm định ngữ (关于……的N).","examples":[["关于这个问题，我们下次再讨论。","Về vấn đề này, lần sau chúng ta thảo luận tiếp.","guān yú zhè ge wèn tí, wǒ men xià cì zài tǎo lùn."],["对于年轻人来说，找到自己的方向非常重要。","Đối với người trẻ, tìm ra hướng đi của mình rất quan trọng.","duì yú nián qīng rén lái shuō, zhǎo dào zì jǐ de fāng xiàng fēi cháng zhòng yào."],["他的失败与缺乏经验有关。","Thất bại của anh ấy có liên quan đến việc thiếu kinh nghiệm.","tā de shī bài yǔ quē fá jīng yàn yǒu guān."]],"compare":"关于 = phạm vi nội dung; 对于 = đối tượng hướng tới; 至于 = chuyển chủ đề.","errors":"Dùng 关于 sau chủ ngữ (✗ 我关于这件事没意见 → 我对于这件事没意见 / 关于这件事，我没意见).","ex":[{"q":"我读了一本___中国历史的书。","o":["关于","对于","对","至于"],"a":0,"e":"Nội dung sách."},{"q":"我们___这件事的态度是一致的。","o":["对于","关于","至于","由于"],"a":0,"e":"Thái độ đối với."},{"q":"这个问题跟环境污染___。","o":["有关","关于","对于","相关于"],"a":0,"e":"跟……有关."},{"q":"Tiêu đề nào đúng?","o":["关于加强安全管理的通知","对于加强安全管理的通知","至于加强安全管理的通知","由于加强安全管理的通知"],"a":0,"e":"Tiêu đề dùng 关于."},{"q":"Câu nào đúng?","o":["他关于这个问题很感兴趣。","他对这个问题很感兴趣。","他至于这个问题很感兴趣。","他有关这个问题很感兴趣。"],"a":1,"e":""}],"id":44},{"title":"被动句：被 / 受到 / 遭到 / 为……所……","formula":"主语 + 被/叫/让 + 施事 + V · 受到 + 欢迎/重视/影响 · 遭到 + 反对/拒绝/破坏 · 为 + 施事 + 所 + V","meaning":"Câu bị động trong văn viết: 受到 (nhận được – thường trung tính/tích cực), 遭到 (gặp phải – tiêu cực), 为……所…… (văn viết trang trọng: bị/được ... ).","usage":"受到 + danh động từ hai âm tiết (欢迎、重视、批评、影响); 遭到 + điều bất lợi (反对、拒绝、破坏、袭击); 为……所 + động từ hai âm tiết (为人所知、为大家所接受).","position":"Sau chủ ngữ, trước tân ngữ là danh động từ.","examples":[["这部电影上映后受到了观众的热烈欢迎。","Bộ phim sau khi công chiếu nhận được sự hoan nghênh nhiệt liệt của khán giả.","zhè bù diàn yǐng shàng yìng hòu shòu dào le guān zhòng de rè liè huān yíng."],["他的建议遭到了大多数人的反对。","Đề xuất của anh ấy bị đa số mọi người phản đối.","tā de jiàn yì zāo dào le dà duō shù rén de fǎn duì."],["这种观点已逐渐为人们所接受。","Quan điểm này đã dần được mọi người chấp nhận.","zhè zhǒng guān diǎn yǐ zhú jiàn wéi rén men suǒ jiē shòu."]],"compare":"被 dùng rộng rãi, thường hàm ý bất lợi trong khẩu ngữ; 受到 có thể tích cực; 遭到 luôn tiêu cực.","errors":"Dùng 遭到 với điều tốt (✗ 遭到欢迎); viết 被欢迎 khi 受到欢迎 tự nhiên hơn.","ex":[{"q":"这位老教授的研究___了国际学术界的重视。","o":["受到","遭到","被到","让到"],"a":0,"e":"Tích cực: 受到."},{"q":"当地的森林___了严重破坏。","o":["遭到","受欢迎","给到","叫到"],"a":0,"e":"Tiêu cực: 遭到."},{"q":"他的作品早已为广大读者___熟知。","o":["所","被","受","让"],"a":0,"e":"为……所……"},{"q":"Câu nào đúng?","o":["这个方案遭到了大家的欢迎。","这个方案受到了大家的欢迎。","这个方案被到了欢迎。","这个方案为大家欢迎所。"],"a":1,"e":""},{"q":"我的自行车___人偷走了。","o":["被","受到","遭到","为"],"a":0,"e":"Khẩu ngữ: 被 + người + V."}],"id":45}];